SELECT v.* FROM ( SELECT t.CREATED_BY, t.project_id, t.project_number, t.contract_number, t.contract_name, t.host_project_manager, t.ASSIST_PROJECT_MANAGER, t.unit_id, t.tenant_id, (SELECT q.bonded_lease_flag FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_ID = t.project_id AND q.DATA_CLASS = 'VIRTUAL_CON' AND q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' )bonded_lease_flag, CASE WHEN t.BUSINESS_TYPE in('T+N_LEASE_FACTORING','T+0_LEASE_FACTORING') THEN (SELECT wm_concat(b.bp_name) FROM hls_bp_master b ,prj_project_bp hclcb WHERE t.PROJECT_ID = hclcb.PROJECT_ID and b.bp_id = hclcb.bp_id and hclcb.bp_type = 'ACCOUNTS_RECEIVABLE' ) WHEN t.BUSINESS_TYPE in('LEASE_WITHOUT_RECOURSE_IN','OPERATING_LEASE_WITHOUT_RECOURSE_IN') THEN (SELECT wm_concat(b.bp_name) FROM hls_bp_master b ,prj_project_bp hclcb WHERE t.PROJECT_ID = hclcb.PROJECT_ID and b.bp_id = hclcb.bp_id and hclcb.bp_type = 'ASSET_TRANSFEROR') ELSE (SELECT wm_concat(b.bp_name) FROM hls_bp_master b ,prj_project_bp hclcb WHERE t.PROJECT_ID = hclcb.PROJECT_ID and b.bp_id = hclcb.bp_id and hclcb.bp_type = 'TENANT') END AS tenant_id_n,
(SELECT a.description FROM sys_user a WHERE a.user_id = t.host_project_manager) host_project_manager_n, (SELECT u.unit_name FROM fnd_org_unit u WHERE u.unit_id = t.unit_id) unit_id_n, (CASE WHEN (SELECT count(*) FROM con_contract_cashflow c, con_contract tt WHERE c.contract_id = tt.contract_id AND c.received_amount < c.due_amount AND trunc(c.due_date) < trunc(sysdate) AND c.cf_item in (1,3) AND c.cf_status != 'BLOCK' AND tt.project_id = t.project_id AND tt.data_class = 'NORMAL' and tt.contract_status in('INCEPT','PENDING') ) > 0 THEN '逾期' ELSE '未逾期' END ) overdue_status_n, (CASE WHEN (SELECT count(*) FROM con_contract_cashflow c, con_contract tt WHERE c.contract_id = tt.contract_id AND c.received_amount < c.due_amount AND trunc(c.due_date) < trunc(sysdate) AND c.cf_item in (1,3) AND c.cf_status != 'BLOCK' AND tt.project_id = t.project_id AND tt.data_class = 'NORMAL' and tt.contract_status in('INCEPT','PENDING') ) > 0 THEN 'Y' ELSE 'N' END ) overdue_status, (SELECT max(c.overdue_max_days) FROM con_contract_cashflow c,con_contract tt WHERE c.contract_id = tt.contract_id AND c.received_amount < c.due_amount AND trunc(c.due_date) < trunc(sysdate) AND c.cf_item IN (1, 3) AND c.cf_status != 'BLOCK' AND tt.project_id = t.project_id AND tt.data_class = 'NORMAL' and tt.contract_status in('INCEPT','PENDING') ) overdue_max_days, (SELECT sum(q.lease_times) FROM con_contract tt,prj_quotation q WHERE tt.project_id = t.project_id AND tt.data_class = 'NORMAL' and tt.quotation_id = q.quotation_id and tt.contract_status in('INCEPT','PENDING') ) lease_times, (SELECT count(*) FROM con_contract_cashflow c, con_contract tt WHERE c.contract_id = tt.contract_id AND c.received_amount < c.due_amount AND trunc(c.due_date) < trunc(sysdate) AND c.cf_item IN (1, 3) AND c.cf_status != 'BLOCK' AND tt.project_id = t.project_id AND tt.data_class = 'NORMAL' and tt.contract_status in('INCEPT','PENDING') ) overdue_times, (SELECT sum(c.due_amount - c.received_amount) FROM con_contract_cashflow c, con_contract tt WHERE c.contract_id = tt.contract_id AND c.received_amount < c.due_amount AND trunc(c.due_date) < trunc(sysdate) AND c.cf_item IN (1, 3) AND c.cf_status != 'BLOCK' AND tt.project_id = t.project_id AND tt.data_class = 'NORMAL' and c.cf_status = 'RELEASE' and tt.contract_status in('INCEPT','PENDING') ) overdue_amount, (SELECT sum(c.principal - c.received_principal) FROM con_contract_cashflow c, con_contract tt WHERE c.contract_id = tt.contract_id AND c.received_amount < c.due_amount AND trunc(c.due_date) < trunc(sysdate) AND c.cf_item IN (1, 3) AND c.cf_status != 'BLOCK' AND tt.project_id = t.project_id AND tt.data_class = 'NORMAL' and c.cf_status = 'RELEASE' and tt.contract_status in('INCEPT','PENDING') ) overdue_principal_amount, (SELECT sum(c.interest - c.received_interest) FROM con_contract_cashflow c, con_contract tt WHERE c.contract_id = tt.contract_id AND c.received_amount < c.due_amount AND trunc(c.due_date) < trunc(sysdate) AND c.cf_item IN (1, 3) AND c.cf_status != 'BLOCK' AND tt.project_id = t.project_id AND tt.data_class = 'NORMAL' and c.cf_status = 'RELEASE' and tt.contract_status in('INCEPT','PENDING') ) overdue_interest_amount, (SELECT sum(c.due_amount) FROM con_contract_cashflow c, con_contract tt WHERE c.contract_id = tt.contract_id AND c.received_amount < c.due_amount AND trunc(c.due_date) < trunc(sysdate) AND c.cf_item = 9 AND tt.project_id = t.project_id AND tt.data_class = 'NORMAL' and c.cf_status = 'RELEASE' ) penalty_amount, t.contract_num FROM prj_project t WHERE t.data_class = 'VIRTUAL_CON' AND t.data_type = 'NORMAL' AND t.contract_status = 'SIGN' AND EXISTS ( SELECT 1 FROM con_contract a WHERE a.project_id = t.project_id AND a.data_class = 'NORMAL' and a.contract_status in('INCEPT','PENDING') ) ) v
1=1
and ( v.created_by = #{createdBy} or v.ASSIST_PROJECT_MANAGER = #{createdBy} or EXISTS (SELECT 1 FROM sys_user U LEFT JOIN SYS_USER_ALLOCATION UR ON UR.USER_ID = U.USER_ID LEFT JOIN SYS_ROLE_B R ON R.ROLE_ID = UR.ROLE_ID WHERE (R.ROLE_CODE = 'ADMIN' or u.user_name ='huliting') and U.USER_ID = #{createdBy}) or EXISTS( SELECT 1 FROM sys_user_allocation sa, fnd_employee_assigns FA, fnd_org_position p WHERE sa.EMPLOYEE_ASSIGN_ID = FA.EMPLOYEE_ASSIGN_ID and FA.position_id=p.position_id and p.POSITION_NAME like '%租后管理岗%' and sa.USER_ID = #{createdBy} ))
and v.contract_number like concat(concat('%',#{contractNumber}),'%')
and v.contract_num like concat(concat('%',#{contractNum}),'%')
and v.contract_name like concat(concat('%',#{contractName}),'%')
and v.tenant_id_n like concat(concat('%',#{tenantIdN}),'%')
and v.host_project_manager_n = #{employeeIdN}
and v.overdue_max_days >= #{overdueMaxDaysFrom}
and v.overdue_max_days <= #{overdueMaxDaysTo}
and v.overdue_amount >= #{overdueAmountFrom}
and v.overdue_amount <= #{overdueAmountTo}
and v.overdue_status = #{overdueStatus}
and EXISTS ( SELECT 1 FROM con_contract a,con_contract_cashflow cc WHERE a.project_id = v.project_id and a.contract_id=cc.contract_id and to_char(cc.due_date,'YYYY-MM-DD') >= #{dueDateFrom} and to_char(cc.due_date,'YYYY-MM-DD') <= #{dueDateTo} )
and EXISTS ( SELECT 1 FROM con_contract a,con_contract_cashflow cc WHERE a.project_id = v.project_id and a.contract_id=cc.contract_id and to_char(cc.due_date,'YYYY-MM-DD') >= #{dueDateFrom})
and EXISTS ( SELECT 1 FROM con_contract a,con_contract_cashflow cc WHERE a.project_id = v.project_id and a.contract_id=cc.contract_id and to_char(cc.due_date,'YYYY-MM-DD') <= #{dueDateTo})

select v.* from ( SELECT p.created_by, p.chance_id, p.project_id, p.project_name, p.project_number, p.project_status, (SELECT max( END_TIME_ ) FROM ACT_HI_PROCINST ahp WHERE ahp.BUSINESS_KEY_ = p.PROJECT_ID and p.project_status='APPROVED' AND INSTR( ahp.PROC_DEF_ID_, 'PROJECT_REVIEW_WFL' ) > 0 ) approved_time, p.data_class, p.business_type, p.project_number as marketing_report_number, (SELECT b.bp_name FROM hls_bp_master b WHERE b.bp_id = p.tenant_id) tenant_id_n, p.tenant_id, CASE WHEN p.credit_flag='N' then (select wm_concat(hbm.bp_name) FROM hls_bp_master hbm, prj_project_bp hclcb WHERE hclcb.project_id = p.project_id and hbm.bp_id = hclcb.bp_id and hclcb.bp_type in ('TENANT','TENANT_SEC')) else (select wm_concat(hbm.bp_name) FROM hls_bp_master hbm, prj_project_bp hclcb WHERE hclcb.project_id = p.project_id and hbm.bp_id = hclcb.bp_id and hclcb.bp_type in ('MANUFACTURER') ) end as tenant_all_name, case when p.credit_flag = 'Y' then (SELECT q.CREDIT_AMT FROM hls_credit_plan q WHERE q.SOURCE_DOCUMENT_ID = p.project_id AND q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT') else (SELECT q.LEASE_ITEM_AMOUNT FROM prj_quotation q WHERE q.QUOTATION_ID = (select max(QUOTATION_ID) from prj_quotation pq where pq.SOURCE_DOCUMENT_ID = p.project_id AND pq.SOURCE_DOCUMENT_CATEGORY like 'PRJ_PROJECT%')) end as lease_item_amount, p.finance_amount, (SELECT s.description FROM sys_user s WHERE s.user_id = p.created_by) created_by_n, nvl(p.credit_flag, 'N') credit_flag, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'SYS.YES_NO' AND v.code_value = nvl(p.credit_flag, 'N')) credit_flag_n, (SELECT hdt.description FROM hls_document_type hdt WHERE hdt.business_type = p.business_type AND hdt.document_category = p.document_category AND hdt.document_type = p.document_type ) AS business_type_n, p.host_project_manager, (SELECT a.description FROM sys_user a WHERE a.user_id=p.host_project_manager) host_project_manager_n, p.unit_id, (SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = p.unit_id) unit_id_n, p.host_unit_id, (SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = p.host_unit_id) host_unit_id_n, p.assist_project_manager, (SELECT a.description FROM sys_user a WHERE a.user_id= p.assist_project_manager) assist_project_manager_n, p.assist_unit_id, (SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = p.assist_unit_id ) assist_unit_id_n, (SELECT fe. NAME FROM fnd_org_unit fou, fnd_org_position fop, fnd_employee_assigns fea, fnd_employee fe WHERE fou.unit_id = p.unit_id AND fou.unit_id = fop.unit_id AND fop.chief_position_flag = 'Y' AND fop.position_id = fea.position_id AND fea.employee_id = fe.employee_id and fe.ENABLED_FLAG = 'Y' and fea.ENABLED_FLAG = 'Y' ) project_manager_n, (SELECT t1.description FROM hls_document_status t1 WHERE t1.document_category = 'PRJ_PROJECT' and t1.enabled_flag = 'Y' AND t1.status_code = p.project_status) project_status_n, (SELECT t1.description FROM hls_document_status t1 WHERE t1.document_category = 'PRJ_PROJECT' and t1.enabled_flag = 'Y' AND t1.status_code = p.project_status) project_status_desc, p.company_id, p.contract_status, p.document_category, p.data_type, p.tenant_sec_id,p.guarantor_id,p.guarantor_np_id FROM prj_project p )v
v.data_class = 'NORMAL' and v.data_type = 'NORMAL'
and ( v.created_by = #{createdBy} or v.assist_project_manager = #{createdBy} or #{request.employeeCode} in('ADMIN') OR exists( select 1 from fnd_org_unit a1,fnd_employee a2,fnd_employee_assigns a3,FND_ORG_POSITION a4 where a3.employee_id=a2.employee_id and a3.unit_id=a1.unit_id and a4.position_id=a3.position_id and a4.chief_position_flag='Y' and employee_code=#{request.employeeCode} AND A1.UNIT_ID IN(select b.unit_id from sys_user_allocation a,fnd_employee_assigns b where a.user_id=v.created_by AND a.employee_assign_id=b.employee_assign_id)))
and v.company_id = #{companyId}
and v.contract_status = #{contractStatus}
and v.project_name like concat(concat('%',#{projectName}),'%')
and v.project_number like concat(concat('%',#{projectNumber}),'%')
and v.project_status = #{projectStatus}
and v.bp_name like concat(concat('%',#{bpName}),'%')
and v.host_project_manager = #{hostProjectManager}
and v.assist_project_manager = #{assistProjectManager}
and v.unit_id = #{unitId}
and v.lease_item_amount >= #{leaseItemAmountFrom}
and v.lease_item_amount <= #{leaseItemAmountTo}
and trunc(v.approved_time) >= to_date(#{approvedTimeFrom},'yyyy-mm-dd')
and trunc(v.approved_time) <= to_date(#{approvedTimeTo},'yyyy-mm-dd')
and v.business_type = #{businessType}
and v.lease_item_amount = #{leaseItemAmount}
and v.project_id = #{projectId}
and ((v.project_number like concat(concat('%',#{params}),'%')) or (v.project_name like concat(concat('%',#{params}),'%')) or (v.bp_name like concat(concat('%',#{params}),'%')))
and (select voting_result from act_meeting am where am.document_id=v.project_id and am.document_category=v.document_category) in ('同意','有条件同意')
and v.tenant_all_name like concat(concat('%',#{tenantAllName}),'%')
and v.tenant_id= #{tenantId}
and v.warrantor_name like concat(concat('%',#{warrantorName}),'%')
and v.host_unit_name like concat(concat('%',#{hostUnitName}),'%')
and v.finance_amount = #{financeAmount}
and v.project_status in ('NOTICE_APPROVED','PENDING')
and v.credit_flag = #{creditFlag}
order by v.project_id desc

select v.* from ( SELECT p.created_by, p.project_id, p.project_name, p.project_number, p.project_status, p.data_class, p.business_type, p.project_number as marketing_report_number, ( SELECT b.bp_name FROM hls_bp_master b WHERE b.bp_id = p.tenant_id ) tenant_id_n, p.tenant_id, (select wm_concat(hbm.bp_name) FROM hls_bp_master hbm, prj_project_bp hclcb WHERE hclcb.project_id = p.project_id and hbm.bp_id = hclcb.bp_id and hclcb.bp_type in ('TENANT','TENANT_SEC','ASSET_TRANSFEROR','ACCOUNTS_RECEIVABLE') )tenant_all_name, (SELECT q.LEASE_ITEM_AMOUNT FROM prj_quotation q WHERE q.SOURCE_DOCUMENT_ID = p.project_id AND q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' AND q.DATA_CLASS = 'PRJ_PROJECT_INVEST')lease_item_amount, p.finance_amount, ( SELECT s.description FROM sys_user s WHERE s.user_id = p.created_by ) created_by_n, nvl(p.credit_flag, 'N') credit_flag, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'SYS.YES_NO' AND v.code_value = nvl(p.credit_flag, 'N') ) credit_flag_n, ( SELECT hdt.description FROM hls_document_type hdt WHERE hdt.business_type = p.business_type AND hdt.document_category = p.document_category AND hdt.document_type = p.document_type ) AS business_type_n, p.host_project_manager, (SELECT a.description FROM sys_user a WHERE a.user_id = p.host_project_manager) host_project_manager_n, p.unit_id, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = p.unit_id ) unit_id_n, p.host_unit_id, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = p.host_unit_id ) host_unit_id_n, p.assist_project_manager, (SELECT a.description FROM sys_user a WHERE a.user_id= p.assist_project_manager) assist_project_manager_n, p.assist_unit_id, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = p.assist_unit_id ) assist_unit_id_n, ( SELECT fe. NAME FROM fnd_org_unit fou, fnd_org_position fop, fnd_employee_assigns fea, fnd_employee fe WHERE fou.unit_id = p.unit_id AND fou.unit_id = fop.unit_id AND fop.chief_position_flag = 'Y' AND fop.position_id = fea.position_id AND fea.employee_id = fe.employee_id and fe.ENABLED_FLAG = 'Y' and fea.ENABLED_FLAG = 'Y' ) project_manager_n, ( SELECT t1.description FROM hls_document_status t1 WHERE t1.document_category = 'PRJ_PROJECT' AND t1.status_code = p.project_status ) project_status_n, ( SELECT t1.description FROM hls_document_status t1 WHERE t1.document_category = 'PRJ_PROJECT' AND t1.status_code = p.project_status ) project_status_desc, p.company_id, p.contract_status, p.document_category, p.data_type, p.tenant_sec_id,p.guarantor_id,p.guarantor_np_id, ppm.meeting_name, ppm.meeting_location, ppm.meeting_date, meeting.meeting_person FROM prj_project p, prj_project_meeting ppm LEFT JOIN (select tab.project_id,tab.PROJECT_MEETING_ID, wm_concat(tab.rowNum,'、',tab.meeting_person) as meeting_person from (SELECT prma.PROJECT_MEETING_ID, concat( '评委：', fee.description, '，岗位：', prma.position_name, '，表决结果：', prma.vote_result, '，表决意见：', prma.vote_comment ) meeting_person, @r:= case when @type=prma.PROJECT_MEETING_ID then @r+1 else 1 end as rowNum, @type:=prma.PROJECT_MEETING_ID as type, prma.PROJECT_ID FROM PRJ_PROJECT_MEETING_APPROVER prma, (select @r:=0 ,@type:='') b, fnd_employee_assigns fe, sys_user_allocation sua LEFT JOIN sys_user fee ON fee.user_id = sua.user_id WHERE sua.employee_assign_id = fe.employee_assign_id AND prma.approver_user_id = sua.allocation_id ) tab group by tab.project_id,tab.PROJECT_MEETING_ID) meeting on meeting.project_id = ppm.project_id /* and meeting.PROJECT_MEETING_ID = ppm.PROJECT_MEETING_ID */ WHERE ppm.PROJECT_ID = p.PROJECT_ID and ppm.DATA_CLASS in ('NORMAL','HISTORY') AND ppm.MEETING_DATE IS NOT NULL )v
