select v.*, nvl((select max((CASE hur.RELATION_DOCUMENT_ID WHEN NULL THEN 'N' ELSE 'Y' END)) from hls_user_relationship hur where v.project_id = hur.RELATION_DOCUMENT_ID and hur.SOURCE_USER_ID = 10001), 'N') collectFlag from (select (SELECT ppcn.project_notice_number FROM prj_project_credit_notice ppcn where ppcn.project_id = p.project_id and ppcn.prj_notice_id = case when (SELECT max(ppcn.prj_notice_id) FROM prj_project_credit_notice ppcn where ppcn.project_id = p.project_id and ppcn.credit_type in( 'APPROVE', 'VETO', 'HOLD') and ppcn.notice_create_date is not null) = null then (SELECT max(ppcn.prj_notice_id) FROM prj_project_credit_notice ppcn where ppcn.project_id = p.project_id and ppcn.notice_create_date is not null) else (SELECT max(ppcn.prj_notice_id) FROM prj_project_credit_notice ppcn where ppcn.project_id = p.project_id and ppcn.credit_type in( 'APPROVE', 'VETO', 'HOLD') and ppcn.notice_create_date is not null) end ) prj_notice_id, (SELECT ppcn.credit_period_from FROM prj_project_credit_notice ppcn where ppcn.project_id = p.project_id and ppcn.prj_notice_id = (SELECT max(ppcn.prj_notice_id) FROM prj_project_credit_notice ppcn where ppcn.project_id = p.project_id and ppcn.notice_create_date is not null)) as credit_period_from, (SELECT ppcn.credit_period_to FROM prj_project_credit_notice ppcn where ppcn.project_id = p.project_id and ppcn.prj_notice_id = (SELECT max(ppcn.prj_notice_id) FROM prj_project_credit_notice ppcn where ppcn.project_id = p.project_id and ppcn.notice_create_date is not null)) as credit_period_to,
(case when p.data_class = 'VIRTUAL_CON' then (select max(ppcn.project_notice_number) project_notice_number from prj_project_credit_notice ppcn where ppcn.project_id = p.ref_project_id and ppcn.credit_type='APPROVE') else (select max(ppcn.project_notice_number) project_notice_number from prj_project_credit_notice ppcn where ppcn.project_id = p.project_id) end ) PROJECT_NOTICE_NUMBER, p.notice_approve_veto, nvl(p.project_status, 'NEW') project_status, (select sum(pq.lease_item_amount) from prj_quotation pq where pq.source_document_id = p.project_id and pq.data_class = 'PRJ_PROJECT_INVEST') as lease_item_amount, (select pq.quotation_id from prj_quotation pq where pq.source_document_id = p.project_id and pq.data_class = 'PRJ_PROJECT_INVEST' and rownum=1) as quotation_id, p.employee_id, p.company_id, p.credit_amount, (select wm_concat(h.bp_name) from prj_project_bp pb, hls_bp_master h where h.bp_id = pb.bp_id and pb.bp_categroy = 'PRJ_PROJECT' and pb.bp_type = 'TENANT' and pb.project_id = p.project_id) as bp_name, p.project_id, p.unit_id, p.data_class, p.data_type, p.approval_amount, nvl(nvl((SELECT pq.lease_item_amount from prj_quotation pq where pq.source_document_id = p.project_id and pq.data_class = 'PRJ_PROJECT_INVEST' and rownum=1), 0) - nvl((SELECT SUM(pp.contract_amount) FROM prj_project pp WHERE pp.data_class = 'VIRTUAL_CON' AND pp.ref_project_id = p.project_id), 0), 0) AS left_amount, (SELECT count(*) FROM prj_project pp WHERE pp.data_class = 'VIRTUAL_CON' AND pp.data_type = 'NORMAL' AND pp.ref_project_id = p.project_id) as virtual_con_counts, (select project_id from prj_project where ref_project_id = p.project_id and data_type = 'CHANGE_REQ' and data_class = 'NORMAL' and change_req_id = (select max(change_req_id) from prj_project where ref_project_id = p.project_id and data_type = 'CHANGE_REQ' and data_class = 'NORMAL')) project_id_new, (select status from change_req_info where document_id = p.project_id and document_category = 'PRJ_PROJECT' and change_req_id 