.UNIT_NAME) UNIT_NAME, SUA.COMPANY_ID FROM SYS_USER_ALLOCATION SUA LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID = FOU.UNIT_ID, ( SELECT MIN(sua.COMPANY_ID) COMPANY_ID, sua.USER_ID FROM SYS_USER_ALLOCATION sua GROUP BY sua.USER_ID ORDER BY sua.USER_ID ASC ) SUAC, FND_EMPLOYEE FE WHERE SUA.COMPANY_ID = FEA.COMPANY_ID AND SUA.COMPANY_ID = FOU.COMPANY_ID AND SUA.COMPANY_ID = SUAC.COMPANY_ID AND SUA.USER_ID = SUAC.USER_ID AND FE.EMPLOYEE_ID = FEA.EMPLOYEE_ID GROUP BY SUA.USER_ID, SUA.COMPANY_ID, FE.NAME ORDER BY SUA.USER_ID ASC ) TABALL4 on p.host_project_manager = TABALL4.USER_ID left join ( SELECT FE.NAME, SUA.USER_ID, MIN(fou.unit_id) unit_id, MIN(FOU.UNIT_NAME) UNIT_NAME, SUA.COMPANY_ID FROM SYS_USER_ALLOCATION SUA LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID = FOU.UNIT_ID, ( SELECT MIN(sua.COMPANY_ID) COMPANY_ID, sua.USER_ID FROM SYS_USER_ALLOCATION sua GROUP BY sua.USER_ID ORDER BY sua.USER_ID ASC ) SUAC, FND_EMPLOYEE FE WHERE SUA.COMPANY_ID = FEA.COMPANY_ID AND SUA.COMPANY_ID = FOU.COMPANY_ID AND SUA.COMPANY_ID = SUAC.COMPANY_ID AND SUA.USER_ID = SUAC.USER_ID AND FE.EMPLOYEE_ID = FEA.EMPLOYEE_ID GROUP BY SUA.USER_ID, SUA.COMPANY_ID, FE.NAME ORDER BY SUA.USER_ID ASC ) TABALL2 on p.assist_project_manager = TABALL2.USER_ID) v
