SELECT * FROM ( SELECT p1.*, bp.tenant_all_name, case when p1.CREDIT_FLAG = 'Y' then hcp1.CREDIT_AMT ELSE pq1.lease_item_amount END AS finance_amount, case when p1.CREDIT_FLAG = 'Y' then (nvl( hcp1.CREDIT_AMT, 0 ) - nvl( sum_contract.contract_amount, 0 )) ELSE (nvl( pq1.lease_item_amount, 0 ) - nvl( sum_contract.contract_amount, 0 )) END AS left_amount, -- nvl( pq1.lease_item_amount, 0 ) - nvl( sum_contract.contract_amount, 0 ) AS left_amount, nvl( sum_contract.contract_amount, 0 ) AS use_amount, pur.PURCHASE_FRAME, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SYS.YES_NO' AND pur.PURCHASE_FRAME = v.CODE_VALUE ) AS PURCHASE_FRAME_n FROM ( SELECT p.PROJECT_ID, p.PROJECT_NUMBER, -- p.finance_amount, PROJECT_NAME, p.host_project_manager, (select s.description from sys_user s where s.user_id = p.host_project_manager) as host_project_manager_n, (select s.description from sys_user s where s.user_id = p.assist_project_manager) as assist_project_manager_n, p.assist_project_manager, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = p.unit_id ) unit_id_n, nvl( p.project_status, 'NEW' ) AS project_status, ( SELECT sc.meaning FROM sys_code_value_b_v sc WHERE sc.CODE = 'PRJ501_PRJ_STATUS' AND sc.CODE_VALUE = nvl( p.project_status, 'NEW' )) AS project_status_n, ( SELECT hdt.description FROM hls_document_type hdt WHERE hdt.business_type = p.business_type AND hdt.document_category = p.document_category AND hdt.document_type = p.document_type ) AS business_type_n, p.business_type as business_type_value, P.COMPANY_ID, p.data_class, p.data_type, p.CREDIT_FLAG, p.CREATED_BY, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SYS.YES_NO' AND p.CREDIT_FLAG = v.CODE_VALUE ) AS credit_flag_n FROM prj_project p WHERE p.data_class = 'NORMAL' AND p.data_type in ('NORMAL', 'CREDIT_NORMAL') AND p.project_status = 'APPROVED' AND p.project_id not in (select jd_project_id from HLS_CREDIT_LINE_CHANCE where jd_project_id is not null) and NVL(p.credit_flag,'N')='N' ) p1 LEFT JOIN ( SELECT ppb.project_id, wm_concat( hls.bp_name ) AS tenant_all_name FROM prj_project_bp ppb, hls_bp_master hls WHERE ppb.bp_id = hls.bp_id AND ppb.BP_TYPE IN ( 'TENANT', 'TENANT_SEC', 'ASSET_TRANSFEROR', 'ACCOUNTS_RECEIVABLE' ) GROUP BY ppb.PROJECT_ID ) bp ON p1.PROJECT_ID = bp.project_id LEFT JOIN ( SELECT nvl( pq.lease_item_amount, 0 ) AS lease_item_amount, pq.source_document_id FROM prj_quotation pq WHERE pq.source_document_category = 'PRJ_PROJECT' ) pq1 ON pq1.source_document_id = p1.project_id LEFT JOIN ( SELECT nvl( hcp.CREDIT_AMT, 0 ) AS CREDIT_AMT, hcp.source_document_id FROM HLS_CREDIT_PLAN hcp WHERE hcp.source_document_category = 'PRJ_PROJECT' ) hcp1 ON hcp1.source_document_id = p1.project_id LEFT JOIN ( SELECT pp.ref_project_id, nvl( SUM( pp.contract_amount ), 0 ) AS contract_amount FROM prj_project pp WHERE pp.data_class = 'VIRTUAL_CON' AND pp.CONTRACT_STATUS != 'CANCEL' AND pp.PURCHASE_FRAME != 'Y' GROUP BY pp.ref_project_id ) sum_contract ON p1.project_id = sum_contract.ref_project_id LEFT JOIN ( SELECT pp.ref_project_id, pp.purchase_frame FROM prj_project pp WHERE pp.data_class = 'VIRTUAL_CON' AND pp.PURCHASE_FRAME = 'Y' ) pur ON p1.project_id = pur.ref_project_id ) v
