select * from ( -- 保理立项 SELECT (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = fpb.bp_id) as bp_name, fc.project_name, concat('CHANCE-',fc.project_status) as project_status, fc.company_id, fc.LAST_UPDATE_DATE FROM fct_chance fc, fct_project_bp fpb WHERE fc.chance_id = fpb.chance_id AND fpb.credit_grantor_party = 'Y' AND NOT EXISTS(select 1 from fct_project fp where fp.chance_id = fc.chance_id) UNION -- 保理尽调 SELECT (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = fpb.bp_id) as bp_name, fp.project_name, concat('PROJECT-',fp.credit_status) as project_status, fp.company_id, fp.LAST_UPDATE_DATE FROM fct_project fp, fct_project_bp fpb WHERE fp.project_id = fpb.project_id AND fp.data_class = 'NORMAL' AND fp.data_type = 'NORMAL' AND fpb.credit_grantor_party = 'Y' UNION -- 租赁立项 SELECT hbm.bp_name, pc.project_name, concat('CHANCE-',pc.project_status) as project_status, pc.company_id, pc.LAST_UPDATE_DATE FROM prj_chance pc, hls_bp_master hbm WHERE pc.tenant_id = hbm.bp_id AND NOT EXISTS(select 1 from prj_project pp where pp.chance_id = pc.chance_id) UNION -- 租赁尽调 SELECT hbm.bp_name, pp.project_name, concat('PROJECT-',pp.project_status) as project_status, pp.company_id, pp.LAST_UPDATE_DATE FROM prj_project pp, hls_bp_master hbm WHERE pp.tenant_id = hbm.bp_id AND pp.data_class = 'NORMAL' AND pp.data_type = 'NORMAL') t1 where 1=1
AND t1.company_id = #{companyId}
order by t1.LAST_UPDATE_DATE desc

