p.document_type) as document_type_desc, nvl(hd.description,pp.division) division_desc, (select t.company_full_name from fnd_company t where t.company_id=pp.company_id) company_name, ( select fou.unit_name from fnd_org_unit fou where fou.unit_id=pp.unit_id )as unit_name, nvl( nvl((SELECT pq.lease_item_amount from prj_quotation pq where pq.source_document_id=pp.ref_project_id and pq.source_document_category='PRJ_PROJECT'),0) - nvl(( SELECT SUM(t.contract_amount) FROM prj_project t WHERE t.data_class = 'VIRTUAL_CON' AND t.data_type = 'NORMAL' AND t.ref_project_id = pp.ref_project_id ),0), 0 ) AS left_amount, (select fe.name from fnd_employee fe where fe.employee_id=pp.employee_id) as project_manager, (select pq.quotation_id from prj_quotation pq where pq.source_document_id=pp.project_id and pq.data_class='VIRTUAL_CON' and pq.source_document_category='PRJ_PROJECT') quotation_id, (SELECT cc.contract_id from con_contract cc where cc.project_id=pp.project_id and cc.data_class='NORMAL')contract_id, (SELECT cc.incept_date from con_contract cc where cc.project_id=pp.project_id and cc.data_class='NORMAL')incept_date, (select pq.lease_item_amount from prj_quotation pq where pq.source_document_id=pp.project_id and pq.data_class='VIRTUAL_CON'and pq.source_document_category='PRJ_PROJECT' ) as lease_item_amount, (SELECT cc.incept_wfl_status from con_contract cc where cc.project_id=pp.project_id and cc.data_class='NORMAL')incept_wfl_status, (select pq.lease_item_amount from prj_quotation pq where pq.source_document_id=pp.ref_project_id and pq.SOURCE_DOCUMENT_CATEGORY='PRJ_PROJECT')approval_amount, ( select DISTINCT (hbt.description) from hls_business_type hbt where hbt.business_type = pp.business_type and hbt.document_category = pp.document_category ) as business_type_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code = 'WHETHER_INSURANCE' and scb.code_id = scvb.code_id and scvb.value = pp.is_low_risk ) as is_low_risk_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code = 'SYS.YES_NO' and scb.code_id = scvb.code_id and scvb.value = pp.is_spv ) as is_spv_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code = 'WHETHER_INSURANCE' and scb.code_id = scvb.code_id and scvb.value = pp.whether_mortgage_registration ) as mortgage_registration_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code = 'IDENTIFICATION_METHOD' and scb.code_id = scvb.code_id and scvb.value = pp.identification_method ) as identification_method_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code = 'WHETHER_INSURANCE' and scb.code_id = scvb.code_id and scvb.value = pp.whether_insurance ) as whether_insurance_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code = 'WHETHER_INSURANCE' and scb.code_id = scvb.code_id and scvb.value = pp.whether_labeling ) as whether_labeling_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code = 'CON.FLOATING_RANGE_METHOD' and scb.code_id = scvb.code_id and scvb.value = pp.floating_range_method ) as floating_range_method_n, ( select scvb.meaning from sys_code_b scb,sys_code_value_b scvb where scb.code = 'PRJ.LEASE_ITEM_TYPE' and scb.code_id = scvb.code_id and scvb.value = pp.lease_item_property ) as lease_item_property_n, (select pq.vat_rate from prj_quotation pq where pq.source_document_id=pp.project_id and pq.source_document_category='PRJ_PROJECT')vat_rate, (select count(1) from prj_project ppt where ppt.CREATE_CONTRACT_STATUS!='APPROVING' and ppt.contract_status!='SIGNING' AND not exists (select 1 from CSH_PAYMENT_REQ_HD ch where ch.SOURCE_DOC_ID=(select cc.CONTRACT_ID from con_contract cc where cc.project_id=ppt.project_Id and cc.DATA_CLASS='NORMAL') and ch.SOURCE_DOC_TYPE='CON_CONTRACT' and ch.PAYMENT_REQ_STATUS='APPROVING') AND not exists (select 1 from con_contract cc where cc.project_id=ppt.project_id and cc.contract_status='PENDING') and ppt.ref_PROJECT_ID=pp.project_id and data_type='NORMAL' and ppt.DATA_CLASS='VIRTUAL_CON') change_count, (select nvl(count(1),0) from prj_project prj where prj.ref_project_id=pp.project_id and prj.data_type='NORMAL' and prj.data_class='VIRTUAL_CON') project_ref_count, (select UNIT_NAME from (SELECT FE.NAME, SUA.USER_ID, MIN(FOU.UNIT_NAME) UNIT_NAME, SUA.COMPANY_ID FROM SYS_USER_ALLOCATION SUA LEFT JOIN FND_EMPLOYEE_ASSIGNS FEA ON SUA.EMPLOYEE_ASSIGN_ID = FEA.EMPLOYEE_ASSIGN_ID LEFT JOIN FND_ORG_UNIT FOU ON FEA.UNIT_ID = FOU.UNIT_ID, ( SELECT MIN(SUA.COMPANY_ID) COMPANY_ID, SUA.USER_ID FROM SYS_USER_ALLOCATION SUA GROUP BY SUA.USER_ID ORDER BY SUA.USER_ID ASC ) SUAC, FND_EMPLOYEE FE WHERE SUA.COMPANY_ID = FEA.COMPANY_ID AND SUA.COMPANY_ID = FOU.COMPANY_ID AND SUA.COMPANY_ID = SUAC.COMPANY_ID AND SUA.USER_ID = SUAC.USER_ID AND FE.EMPLOYEE_ID = FEA.EMPLOYEE_ID GROUP BY SUA.USER_ID, SUA.COMPANY_ID, FE.NAME ORDER BY SUA.USER_ID ASC) where USER_ID = pp.employee_id) UNIT_MANAGER, FROM prj_project pp LEFT JOIN hls_division hd on pp.division=hd.division and pp.company_id = hd.company_id
1=1
