select @ROWNO := @ROWNO + 1 AS seq_num, tab.* from(select cc.contract_id, ( select YEAR(max(cwo.write_off_date)) from csh_write_off cwo where cwo.contract_id = cc.contract_id and cwo.write_off_type = 'PAYMENT_DEBT' )year, ( select max(cwo.write_off_date) from csh_write_off cwo where cwo.contract_id = cc.contract_id and cwo.write_off_type = 'PAYMENT_DEBT' )apply_pay_date, ( select pp.location from prj_project pp where pp.project_id = cc.project_id )location, ( select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = cc.tenant_id )bp_name, ( select vb.MEANING from hls_bp_master hbm, sys_code_b b, sys_code_value_b vb where hbm.bp_id = cc.tenant_id and b.CODE_ID = vb.CODE_ID and b.CODE = 'FND.ENTERPRISE_LEGAL_FORM' and hbm.legal_form = vb.VALUE )legal_form, ( select nvl(ln.amount_paid,0) from csh_payment_req_ln ln, csh_payment_req_hd hd where ln.payment_req_id = hd.payment_req_id and hd.document_type = 'CON_CONTRACT' and ln.source_doc_id = cc.contract_id )amount_paid, ( nvl(( select ln.amount_paid from csh_payment_req_ln ln, csh_payment_req_hd hd where ln.payment_req_id = hd.payment_req_id and hd.document_type = 'CON_CONTRACT' and ln.source_doc_id = cc.contract_id ),0) - nvl( ( select nvl(sum(ccc.received_principal),0) from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and cf_item = 1 ),0) )amount_rest, cc.lease_term, ( select ccc.due_date from con_contract_cashflow ccc where ccc.contract_id = cc.contract_id and cf_item = 8 )due_date, ( select nvl(pq.xirr,0) from prj_quotation pq where pq.quotation_id = cc.quotation_id )irr, ( select nvl(pq.int_rate,0) from prj_quotation pq where pq.quotation_id = cc.quotation_id )par_interest_rate, ( select nvl(pq.lease_charge_ratio,0) from prj_quotation pq where pq.quotation_id = cc.quotation_id )lease_charge_ratio, ( select nvl(pq.lease_charge,0) from prj_quotation pq where pq.quotation_id = cc.quotation_id )lease_charge, ( select nvl(pq.deposit_ratio,0) from prj_quotation pq where pq.quotation_id = cc.quotation_id )deposit_ratio, ( select nvl(pq.deposit,0) from prj_quotation pq where pq.quotation_id = cc.quotation_id )deposit, ( select wm_concat(vb.MEANING) from prj_project_bp ppb, sys_code_b b, sys_code_value_b vb where ppb.project_id = cc.project_id and b.CODE_ID = vb.CODE_ID and b.CODE = 'CON.GUARANTEE_TYPE' and ppb.guarantee_type = vb.VALUE )guarantee_type, cc.business_type, ( select DISTINCT (hbt.description) from hls_business_type hbt where hbt.business_type = cc.business_type and hbt.document_category = cc.document_category )business_type_desc, ( select pp.subject_matter_introdution from prj_project pp where pp.project_id = cc.project_id )subject_matter_introdution, (select wm_concat(CONCAT(hbm.bp_name,' ',nvl(lcp.financing_amount/100000000,0),'亿')) from hls_bp_master hbm, lon_contract_purpose lcp, lon_contract lc where hbm.bp_id = lc.credit_bp_id and lcp.purpose_doc_id = cc.contract_id and lcp.purpose_doc_category = 'CON_CONTRACT' and lc.contract_id = lcp.contract_id and lc.credit_bp_id not in (18,19) )other_source, (select wm_concat(CONCAT(hbm.bp_name,' ',nvl(lcp.financing_amount/100000000,0),'亿')) from hls_bp_master hbm, lon_contract_purpose lcp, lon_contract lc where hbm.bp_id = lc.credit_bp_id and lcp.purpose_doc_id = cc.contract_id and lcp.purpose_doc_category = 'CON_CONTRACT' and lc.contract_id = lcp.contract_id and lc.credit_bp_id in (18,19) )mother_source, ( select FE.NAME from fnd_employee fe where fe.employee_id = cc.employee_id )project_manager, ( select case when ( select COUNT(1) from ct_abs_contract cac where cac.contract_id = cc.contract_id ) >0 then '是' else '否' end )abs, ( select case when ( select COUNT(1) from ct_abs_contract cac where cac.contract_id = cc.contract_id ) >0 then 'Y' else 'N' end )abs_string from con_contract cc where ( ( cc.data_class = 'NORMAL' AND cc.contract_status = 'INCEPT' ) OR ( cc.data_class = 'NORMAL' AND cc.contract_status = 'PENDING' AND ( SELECT count(0) FROM con_contract ccc WHERE ccc.ref_contract_id = cc.contract_id and ccc.contract_status='INCEPT' and ccc.data_class='CHANGE_REQ' ) > 0 ) ) )tab,(select @rowno:=0) t where 1 = 1
and tab.abs_string in
#{item}
and tab.business_type in
#{item}
and tab.project_manager like concat(concat('%',#{managerName}),'%')
and tab.bp_name like concat(concat('%',#{bpName}),'%')
and tab.year >=#{yearFrom}
and tab.year <=#{yearTo}
and tab.apply_pay_date >= to_date(#{dateFrom},'YYYY-MM-DD')
and tab.apply_pay_date <= to_date(#{dateTo},'YYYY-MM-DD')
and tab.due_date >= to_date(#{dateValidFrom},'YYYY-MM-DD')
and tab.due_date <= to_date(#{dateValidTo},'YYYY-MM-DD')
and tab.amount_paid >=#{trxAmountFrom}
and tab.amount_paid <=#{trxAmountTo}
and tab.amount_paid <=#{amountTo} and tab.amount_paid >=#{amountFrom}

select (select pq.quotation_id from prj_quotation pq where pq.source_document_id = pp.project_id and pq.data_class = 'PRJ_PROJECT_INVEST' and rownum=1) as quotation_id, pp.project_id, pp.credit_line_id, pp.fin_statement_hd_id,
pp.tenant_id, pp.tenant_sec_id, pp.guarantor_id, pp.guarantor_np_id, pp.marketing_report_id, (select hmr.marketing_report_number from hls_marketing_report hmr where hmr.marketing_report_id = pp.marketing_report_id) marketing_report_number, (select count(1) from prj_project_bp ppb where ppb.project_id = pp.project_id and ppb.bp_type = 'TENANT_SEC') tenant_sec_count, (select count(1) from prj_project_bp ppb, hls_bp_master hls where ppb.project_id = pp.project_id and ppb.bp_id = hls.bp_id and ppb.bp_type = 'WARRANTOR' and hls.bp_class = 'ORG') warrantor_count, (select count(1) from prj_project_bp ppb, hls_bp_master hls where ppb.project_id = pp.project_id and ppb.bp_id = hls.bp_id and ppb.bp_type = 'WARRANTOR' and hls.bp_class = 'NP') warrantor_count_np, (select count(1) from hls_marketing_report_bp hmeb where hmeb.marketing_report_id = pp.marketing_report_id and hmeb.bp_type = 'TENANT_SEC') tenant_sec_max, (select count(1) from hls_marketing_report_bp hmeb,hls_bp_master hls where hmeb.marketing_report_id = pp.marketing_report_id and hmeb.bp_id = hls.bp_id and hmeb.bp_type = 'WARRANTOR' and hls.bp_class = 'ORG') warrantor_max, (select count(1) from hls_marketing_report_bp hmeb,hls_bp_master hls where hmeb.marketing_report_id = pp.marketing_report_id and hmeb.bp_id = hls.bp_id and hmeb.bp_type = 'WARRANTOR' and hls.bp_class = 'NP') warrantor_max_np, pp.change_req_id
from prj_project pp where pp.project_id = #{projectId}

select v.* , nvl((select max(( CASE hur.RELATION_DOCUMENT_ID WHEN NULL THEN 'N' ELSE 'Y' END )) from hls_user_relationship hur where v.project_id = hur.RELATION_DOCUMENT_ID and hur.SOURCE_USER_ID = 10001),'N') collectFlag from( select nvl(p.project_status,'NEW') project_status, cc.inception_of_lease , p.company_id, p.credit_amount, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id=p.tenant_id) as bp_name, p.project_id, p.data_class, p.employee_id, p.data_type, p.unit_id, p.contract_name, p.contract_status, p.contract_number, p.contract_amount, p.project_number, p.project_name, p.CREATION_DATE, p.CREATED_BY, nvl(hd.description,p.division) division_desc, (select hdt.description from hls_document_type hdt where hdt.business_type=p.business_type and hdt.document_category=p.document_category and hdt.document_type=p.document_type) as document_type_desc, hds.description project_status_desc, hds1.description contract_status_desc, p.business_type business_type, p.division division, p.tenant_id tenant_id, p.create_contract_status, hds2.description create_contract_status_desc, p.approval_number, p.currency, (select scb.MEANING from SYS_CODE_VALUE_B scb where scb.code_Id in(select code_id from SYS_CODE_B where code='FCT.ACCOUNT_CURRENCY') and scb.value=p.currency)currency_desc, nvl((select sum(cprl.AMOUNT_PAID) from csh_payment_req_ln cprl where cprl.PAYMENT_REQ_ID in (select hd.PAYMENT_REQ_ID from CSH_PAYMENT_REQ_HD hd where hd.SOURCE_DOC_ID in(select cc.CONTRACT_ID from CON_CONTRACT cc where cc.PROJECT_ID=p.project_id and data_class='NORMAL'))),0) amount_paid from prj_project p LEFT JOIN hls_division hd on p.division=hd.division and p.company_id = hd.company_id LEFT JOIN (select * from hls_document_status t1 where t1.document_category='PRJ_PROJECT') hds on hds.status_code=nvl(p.project_status,'NEW') LEFT JOIN (select * from hls_document_status t1 where t1.document_category='CON_CONTRACT') hds1 on hds1.status_code=nvl(p.contract_status,'NEW') LEFT JOIN (select * from hls_document_status t1 where t1.document_category='PRJ_PROJECT') hds2 on hds2.status_code=nvl(p.create_contract_status,'NEW') left join con_contract cc on cc.project_id = p.project_id left join prj_quotation pq on cc.contract_id = pq.source_document_id ) v
v.data_class = 'VIRTUAL_CON' and v.data_type = 'NORMAL' and (v.created_by = #{request.userId} or EXISTS (select 1 from fnd_employee fe where fe.employee_id = v.employee_id and fe.employee_code = #{request.employeeCode}) or 10001=#{request.userId} or ('SALES' NOT IN (SELECT fp.position_code FROM sys_user_allocation sa, fnd_employee_assigns fea, sys_user s,fnd_org_position fp WHERE sa.employee_assign_id = fea.employee_assign_id AND fea.position_id = fp.position_id AND sa.user_id = s.user_id AND fea.enabled_flag = 'Y' AND s.User_Id = #{request.userId})) or EXISTS (select 1 from sys_user_authority_trx suat where suat.user_id=#{request.userId} and suat.document_category='CON_CONTRACT_VIRTUAL' and suat.document_id=v.project_id and suat.authority_source_type='Y'))
and v.company_id = #{companyId}
and v.project_status = #{projectStatus}
and v.contract_status = #{contractStatus}
and v.project_name like concat(concat('%',#{projectName}),'%')
and v.project_number like concat(concat('%',#{projectNumber}),'%')
and v.project_id = #{projectId}
and ((v.project_number like concat(concat('%',#{params}),'%')) or (v.project_name like concat(concat('%',#{params}),'%')) or (v.bp_name like concat(concat('%',#{params}),'%')) or (v.contract_number like concat(concat('%',#{params}),'%')) or (v.APPROVAL_NUMBER like concat(concat('%',#{params}),'%')))
and v.contract_name like concat(concat('%',#{contractName}),'%')
and v.contract_number like concat(concat('%',#{contractNumber}),'%')
and v.bp_name like concat(concat('%',#{bpName}),'%')
and v.contract_amount >= #{financeAmountFrom}
and v.contract_amount <= #{financeAmountTo}
and v.business_type = #{businessType}
order by v.CREATION_DATE desc

select * from (select pq.quotation_id, pp.project_id, cc.contract_id, cc.contract_status, cc.incept_flag , (case when cc.contract_status ='INCEPT' then '起租' else '未起租' end) contract_status_desc, cc.contract_number as payment_number, pp.contract_number as contract_number, pp.project_number as project_number, pp.project_name as project_name, (SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = pp.host_unit_id) AS unit_name, (select fc.company_full_name FROM fnd_company fc where fc.company_id = pp.company_spv )company_name, hbm.bp_name as bp_name, pq.lease_account_date, pp.loan_initial_lease, (select scv.MEANING from sys_code_b sc,sys_code_value_b scv where sc.CODE_ID = scv.CODE_ID and sc.CODE = 'SYS.YES_NO' and scv.value = pp.loan_initial_lease) loan_initial_lease_n, pq.lease_account_date_delay, pq.financial_lease_flag, cc.fin_loan_initial_lease, (SELECT scv.MEANING FROM sys_code_b sc, sys_code_value_b scv WHERE sc.CODE_ID = scv.CODE_ID AND sc.CODE = 'SYS.YES_NO' AND scv.value = nvl(cc.FIN_LOAN_INITIAL_LEASE,'N')) AS fin_loan_initial_lease_n,
( case when nvl(pq.financial_lease_flag, 'N') = 'N' then '未起租' else '起租' end) financial_lease_status
from prj_quotation pq, con_contract cc, prj_project pp left join hls_bp_master hbm on hbm.bp_id = pp.tenant_id where pp.project_id = cc.project_id and cc.contract_id = pq.source_document_id and pq.source_document_category = 'CON_CONTRACT'
) v
v.incept_flag = 'Y' and nvl(v.financial_lease_flag, 'N') = 'Y'
and v.payment_number like #{paymentNumber}
and v.contract_number like #{contractNumber}
and v.lease_account_date > #{leaseAccountDateFrom}
and v.lease_account_date < #{leaseAccountDateTo}
order by v.lease_account_date desc

select t.* from (select p.project_id, p.approval_id, (select ppm.meeting_name from prj_project_meeting ppm where ppm.project_meeting_id = ppa.meeting_id) meeting_name, p.project_number, p.meeting_type, (select ppa.project_attachment_id from prj_project_attachment ppa where ppa.project_attachment_category = 'PRJ_REVIEW_REPORT' and ppa.project_id = p.project_id and rownum=1) project_attachment_id, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code = 'PRJ.MEETING_TYPE' and scb.code_id = scvb.code_id and scvb.value = p.meeting_type) as meeting_type_n, p.marketing_report_id, hmr.marketing_report_number, p.project_name, p.tenant_id, (select bp_name from hls_bp_master h where h.bp_id = p.tenant_id and h.enabled_flag = 'Y') as bp_name, p.tenant_sec_id, p.tenant_sec_id_n tenant_sec_id_n, p.guarantor_id, (select count(1) from prj_project_bp ppb where ppb.project_id = p.project_id and ppb.bp_type = 'TENANT_SEC') tenant_sec_count, (select wm_concat(hls.bp_name) from prj_project_bp ppb,hls_bp_master hls where ppb.project_id = p.project_id and ppb.bp_id = hls.bp_id and ppb.bp_type = 'WARRANTOR') warrantor_name, p.FINANCE_AMOUNT as lease_item_amount, p.process_instance_id, p.business_type, (select DISTINCT (hbt.description) from hls_business_type hbt where hbt.business_type = p.business_type and hbt.document_category = p.document_category) as business_type_n, P.host_project_manager, (select s.description from sys_user s where s.user_id = p.host_project_manager) host_project_manager_n, p.host_unit_id, (select fou.unit_name from fnd_org_unit fou where fou.unit_id = p.host_unit_id) host_unit_name, p.assist_project_manager, (select s.description from sys_user s where s.user_id = p.assist_project_manager) assist_project_manager_n, p.assist_unit_id, (select fou.unit_name from fnd_org_unit fou where fou.unit_id = p.assist_unit_id) assist_unit_name, p.approval_status, p.creation_date, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb.code = 'PRJ.MEETING_STATUS' and scb.code_id = scvb.code_id and scvb.value = p.approval_status) as approval_status_n from prj_project p left join prj_project_approval ppa on ppa.approval_id = p.approval_id left join hls_marketing_report hmr on p.marketing_report_id = hmr.marketing_report_id WHERE p.data_type != 'HISTORY' AND p.data_class = 'NORMAL') t
t.approval_status != 'CANCEL' and t.approval_status != 'REJECTED' and t.approval_status is not null
