able_pk_value = t.project_attachment_id)+ (select decode(count(*),0,0,1) from prj_project_attachment t,hls_doc_file_templet ht,fnd_atm_attachment fa,fnd_atm_attachment_multi fm where t.source_id = ht.templet_id and t.project_id = pp.project_id and ht.templet_code = 'DEALER_BUSINESS_CONFIRM' and fa.source_type_code = 'fnd_atm_attachment_multi' and fa.source_pk_value = fm.record_id and fm.table_name = 'prj_project_attachment' and fm.table_pk_value = t.project_attachment_id),8,'Y','N') file_flag, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'SYS.YES_NO' AND v.code_value = decode(decode(hbm.marital_status,'MARRIED',decode((select count(*) from prj_project_attachment t,hls_doc_file_templet ht,fnd_atm_attachment fa,fnd_atm_attachment_multi fm where t.source_id = ht.templet_id and t.project_id = pp.project_id and ht.templet_code = 'MARRIAGE_CERTIFICATE' and fa.source_type_code = 'fnd_atm_attachment_multi' and fa.source_pk_value = fm.record_id and fm.table_name = 'prj_project_attachment' and fm.table_pk_value = t.project_attachment_id),0,0,1),1)+ (select decode(count(*),0,0,1) from prj_project_attachment t,hls_doc_file_templet ht,fnd_atm_attachment fa,fnd_atm_attachment_multi fm where t.source_id = ht.templet_id and t.project_id = pp.project_id and ht.templet_code = 'SIGN_ID_CARD' and fa.source_type_code = 'fnd_atm_attachment_multi' and fa.source_pk_value = fm.record_id and fm.table_name = 'prj_project_attachment' and fm.table_pk_value = t.project_attachment_id)+ (select decode(count(*),0,0,1) from prj_project_attachment t,hls_doc_file_templet ht,fnd_atm_attachment fa,fnd_atm_attachment_multi fm where t.source_id = ht.templet_id and t.project_id = pp.project_id and ht.templet_code = 'MARRYIAGE_REGISTER' and fa.source_type_code = 'fnd_atm_attachment_multi' and fa.source_pk_value = fm.record_id and fm.table_name = 'prj_project_attachment' and fm.table_pk_value = t.project_attachment_id)+ (select decode(count(*),0,0,1) from prj_project_attachment t,hls_doc_file_templet ht,fnd_atm_attachment fa,fnd_atm_attachment_multi fm where t.source_id = ht.templet_id and t.project_id = pp.project_id and ht.templet_code = 'SIGN_PAYMENT_CONFIRM' and fa.source_type_code = 'fnd_atm_attachment_multi' and fa.source_pk_value = fm.record_id and fm.table_name = 'prj_project_attachment' and fm.table_pk_value = t.project_attachment_id)+ (select decode(count(*),0,0,1) from prj_project_attachment t,hls_doc_file_templet ht,fnd_atm_attachment fa,fnd_atm_attachment_multi fm where t.source_id = ht.templet_id and t.project_id = pp.project_id and ht.templet_code = 'SIGN_PURCHASE_CONTRACT' and fa.source_type_code = 'fnd_atm_attachment_multi' and fa.source_pk_value = fm.record_id and fm.table_name = 'prj_project_attachment' and fm.table_pk_value = t.project_attachment_id)+ (select decode(count(*),0,0,1) from prj_project_attachment t,hls_doc_file_templet ht,fnd_atm_attachment fa,fnd_atm_attachment_multi fm where t.source_id = ht.templet_id and t.project_id = pp.project_id and ht.templet_code = 'VEHICLES_INVOICE' and fa.source_type_code = 'fnd_atm_attachment_multi' and fa.source_pk_value = fm.record_id and fm.table_name = 'prj_project_attachment' and fm.table_pk_value = t.project_attachment_id)+ (select decode(count(*),0,0,1) from prj_project_attachment t,hls_doc_file_templet ht,fnd_atm_attachment fa,fnd_atm_attachment_multi fm where t.source_id = ht.templet_id and t.project_id = pp.project_id and ht.templet_code = 'VEHICLE_CERTIFICATE' and fa.source_type_code = 'fnd_atm_attachment_multi' and fa.source_pk_value = fm.record_id and fm.table_name = 'prj_project_attachment' and fm.table_pk_value = t.project_attachment_id)+ (select decode(count(*),0,0,1) from prj_project_attachment t,hls_doc_file_templet ht,fnd_atm_attachment fa,fnd_atm_attachment_multi fm where t.source_id = ht.templet_id and t.project_id = pp.project_id and ht.templet_code = 'DEALER_BUSINESS_CONFIRM' and fa.source_type_code = 'fnd_atm_attachment_multi' and fa.source_pk_value = fm.record_id and fm.table_name = 'prj_project_attachment' and fm.table_pk_value = t.project_attachment_id),8,'Y','N')) file_flag_n FROM prj_project pp LEFT JOIN hls_bp_master hbm ON pp.tenant_id = hbm.bp_id LEFT JOIN hls_document_type hdt ON pp.DOCUMENT_TYPE = hdt.document_type LEFT JOIN con_contract cc ON pp.project_id = cc.project_id LEFT JOIN con_contract_cashflow ccc ON cc.contract_id = ccc.contract_id AND ccc.cf_item = 0 LEFT JOIN (SELECT ccc.cashflow_id, sl.creation_date, sl.slip_status, row_number() over(PARTITION BY ccc.cashflow_id ORDER BY sl.creation_date) as row_flag from CSH_PAYMENT_REQ_SLIP sl, csh_payment_req_slip_ln sln, CSH_PAYMENT_REQ_LN LN, con_contract_cashflow ccc WHERE sl.slip_id = sln.slip_id AND sln.document_id = ln.payment_req_ln_id AND ln.source_doc_line_id = ccc.cashflow_id AND ccc.cf_item = 0 AND sl.slip_status != 'REJECTED') s2 ON CCC.CASHFLOW_ID = s2.cashflow_id and s2.row_flag = 1 LEFT JOIN (SELECT ccc.cashflow_id, hd.creation_date, hd.PAYMENT_REQ_STATUS, row_number() over(PARTITION BY ccc.cashflow_id ORDER BY hd.creation_date) as row_flag from CSH_PAYMENT_REQ_hd hd, CSH_PAYMENT_REQ_LN ln, con_contract_cashflow ccc WHERE hd.payment_req_id = ln.payment_req_id AND ln.SOURCE_DOC_LINE_ID = ccc.CASHFLOW_ID AND ccc.cf_item = 0 AND hd.PAYMENT_REQ_STATUS != 'BACK') s3 ON CCC.CASHFLOW_ID = s3.cashflow_id and s3.row_flag = 1 where pp.project_status = 'APPROVED' and pp.lease_channel = '10' and pp.sign_status in ('REJECTED','NEW','CANCEL') -- and pp.sign_type = 'SIGN_ONLINE' -- and (CASE -- WHEN cc.contract_id is not null THEN -- 'APPROVED' -- ELSE -- pp.sign_status -- END in ('REJECTED','NEW','CANCEL')) ) v
and (exists (select 1 from sys_user_allocation sua, sys_user_authority_rule suar where sua.allocation_id = suar.allocation_id and sua.enabled_flag = 'Y' and suar.enabled_flag = 'Y' and sua.user_id = #{user_id} and suar.document_category = 'PRJ_PROJECT' and v.authority_rule_string like suar.authority_rule_string) or v.project_id IN (SELECT document_id FROM SYS_USER_AUTHORITY_TRX suat WHERE suat.document_category = 'PRJ_PROJECT' AND suat.document_id = v.project_id AND suat.user_id = #{user_id}) or not exists (select 1 from sys_user_allocation sua, sys_user_authority_rule suar where sua.allocation_id = suar.allocation_id and sua.enabled_flag = 'Y' and suar.enabled_flag = 'Y' and sua.user_id = #{user_id} and suar.document_category = 'PRJ_PROJECT'))
and v.file_flag = #{file_flag}
and (v.created_by = #{user_id} or exists( select 1 from fnd_org_unit fu, sys_user_allocation su,fnd_employee_assigns fa where su.user_id=#{user_id} and su.EMPLOYEE_ASSIGN_ID=fa.EMPLOYEE_ASSIGN_ID and fa.unit_id =fu.unit_id and fu.unit_code != 'BUSINESS_DEPT_MANUFACTURER') )
and v.bp_id_vender = #{bp_id}
and v.sign_status = #{sign_status}
and v.bp_name like concat('%',concat(#{bp_name},'%'))
and v.factory_name like concat('%',concat(#{factory_name},'%'))
and v.bp_id_vender_n like concat('%',concat(#{vendor},'%'))
and trunc(v.creation_date) >= to_date(#{creation_date_from},'yyyy-mm-dd')
and trunc(v.creation_date) <= to_date(#{creation_date_to},'yyyy-mm-dd')
and v.project_name like concat('%',concat(#{project_name},'%'))
and v.document_type = #{document_type}
and v.project_status = #{project_status}
and v.project_number = #{project_number}
and v.business_status = #{business_status}
and v.confirm_status = #{confirm_status}
order by v.project_id desc

SELECT v.* FROM ( SELECT ( SELECT hbt.description FROM hls_bp_type hbt WHERE hbt.bp_type = hbm.BP_TYPE ) bp_type_n, pp.project_id, pp.project_name, pp.project_number, pp.project_status, pp.document_type, pp.creation_date, (SELECT max( END_TIME_ ) FROM ACT_HI_PROCINST ahp WHERE ahp.BUSINESS_KEY_ = pp.PROJECT_ID AND INSTR( ahp.PROC_DEF_ID_, 'PRJ_PROJECT' ) > 0 and pp.project_status='APPROVED' ) approved_time, hbm.bp_name, hbm.bp_class, (SELECT hbt.description AS value_name FROM hls_business_type hbt WHERE hbt.document_category = 'HLS_BP_MASTER' AND hbt.business_type=hbm.bp_class) bp_class_n, pq.FINANCE_AMOUNT, pp.sign_type, pp.employee_id, pp.created_by, pp.org_sign_state, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'ORG_SIGN_STATE' AND v.ENABLED_FLAG = 'Y' AND v.code_value = pp.org_sign_state ) org_sign_state_n, pp.GUARANTEE_SIGNED_FLAG, ( SELECT s.MEANING FROM sys_code_value_b_v s WHERE s.CODE = 'GUARANTEE_SIGNED_FLAG' AND s.code_value = pp.guarantee_signed_flag ) guarantee_signed_flag_n, pp.lease_organization, ( SELECT fou.UNIT_NAME FROM fnd_org_unit fou WHERE pp.LEASE_ORGANIZATION = fou.UNIT_CODE AND fou.ENABLED_FLAG = 'Y' ) lease_organization_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SIGN_METHOD' AND v.code_value = pp.sign_type ) sign_type_n, hdt.description document_type_n, ( SELECT fe.NAME FROM fnd_employee fe WHERE fe.employee_id = pp.employee_id ) employee_id_n, ( SELECT fe.NAME FROM fnd_employee fe WHERE fe.employee_id = pp.EMPLOYEE_ID_OF_MANAGER ) employee_id_of_manager_n, ( SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'PRJ501_PRJ_STATUS' AND v.code_id = b.code_id AND v. VALUE = pp.project_status ) project_status_n, --pp.pre_status, /*( SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'PRJ501_PRE_STATUS' AND v.code_id = b.code_id AND v. VALUE = pp.pre_status ) pre_status_n,*/ pp.business_type, (SELECT hdt.description FROM hls_document_type hdt WHERE hdt.business_type = pp.business_type AND hdt.document_category = pp.document_category AND hdt.document_type = pp.document_type ) AS business_type_n, pp.lease_channel, ( SELECT hlc.description FROM hls_lease_channel hlc WHERE hlc.lease_channel = pp.lease_channel ) lease_channel_n, pp.bp_id_vender, ( SELECT hb.bp_name FROM hls_bp_master hb WHERE hb.bp_id = pp.bp_id_vender ) bp_id_vender_n, ( SELECT hbv.bp_name FROM hls_bp_master hbv WHERE hbv.bp_id = pp.factory_id ) factory_name, ( SELECT hbv.bp_code FROM hls_bp_master hbv WHERE hbv.bp_id = pp.manufacturer_id ) manufacturer_code, ( SELECT hbv.bp_name FROM hls_bp_master hbv WHERE hbv.bp_id = pp.manufacturer_id ) manufacturer_name, pp.rejected_date, pp.rejected_description, pp.return_stage, ( SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'RETURN_STAGE' AND v.code_id = b.code_id AND v. VALUE = pp.return_stage ) return_stage_n, pp.return_type, ( SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'SIGN_RETURN_TYPE' AND v.code_id = b.code_id AND v. VALUE = pp.return_type ) return_type_n, PP.PARTNERS_CONTRACT_NUMBER, pp.partners_payment_number, pp.MANUFACTURER_ID, pp.TENANT_ID, pp.division, ( SELECT t.description FROM hls_division t WHERE t.division = pp.division AND t.enabled_flag = 'Y' ) division_n, pp.partners_contract_status, (SELECT sv.MEANING FROM sys_code_value_b sv, sys_code_b b WHERE b.CODE = 'SY_CONTRACT_STATUS' AND sv.code_id = b.code_id AND sv.VALUE= pp.partners_contract_status) partners_contract_status_n, pp.pre_status, (select s.meaning from sys_code_value_b_v s where s.code = 'PRJ501_PRE_STATUS' and s.code_value = pp.pre_status) pre_status_n, pp.order_status, (select s.meaning from sys_code_value_b_v s where s.code = 'PRJ501_ORDER_STATUS' and s.code_value = pp.order_status) order_status_n, (SELECT sv.MEANING FROM sys_code_value_b sv, sys_code_b b WHERE b.CODE = 'DRIVER_AND_APPLICANT' AND sv.code_id = b.code_id AND sv.VALUE= pp.driver_and_applicant) driver_and_applicant FROM prj_project pp LEFT JOIN hls_bp_master hbm ON pp.TENANT_ID = hbm.bp_id LEFT JOIN hls_document_type hdt ON pp.DOCUMENT_TYPE = hdt.document_type LEFT JOIN prj_quotation pq ON pp.PROJECT_ID = pq.source_document_id ) v
v.PROJECT_STATUS IN ('NEW','REJECTED','APPROVED_RETURN','CONDITIONAL','APPROVING','APPROVED','BUSINESSAPPROVED') and v.DOCUMENT_TYPE IN ('PRJL','PRJLB')
and (v.created_by = #{createdBy} or exists( select 1 from fnd_org_unit fu, sys_user_allocation su,fnd_employee_assigns fa where su.user_id=#{createdBy} and su.EMPLOYEE_ASSIGN_ID=fa.EMPLOYEE_ASSIGN_ID and fa.unit_id =fu.unit_id and fu.unit_code != 'BUSINESS_DEPT_MANUFACTURER') )
and v.division = #{division}
and v.bp_id = #{bpId}
and v.bp_name like concat('%',concat(#{bpName},'%'))
and v.bp_id_vender_n like concat('%',concat(#{vendor},'%'))
and trunc(v.creation_date) >= to_date(#{creationDateFrom},'yyyy-mm-dd')
and trunc(v.creation_date) <= to_date(#{creationDateTo},'yyyy-mm-dd')
and trunc(v.approved_time) >= to_date(#{approvedTimeFrom},'yyyy-mm-dd')
and trunc(v.approved_time) <= to_date(#{approvedTimeTo},'yyyy-mm-dd')
and v.factory_name like concat('%',concat(#{factoryName},'%'))
and v.manufacturer_name like concat('%',concat(#{manufacturerName},'%'))
and v.project_id = #{projectId}
and v.project_name like concat('%',concat(#{projectName},'%'))
and v.project_number like concat('%',concat(#{projectNumber},'%'))
and v.employee_id = #{employeeId}
and v.employee_id_of_manager = #{employeeIdOfManager}
and v.lease_channel = #{leaseChannel}
and v.document_type = #{documentType}
and v.project_status = #{projectStatus}
and v.partners_contract_number like concat('%',concat(#{partnersContractNumber},'%'))
and v.partners_payment_number like concat('%',concat(#{partnersPaymentNumber},'%'))
and v.signed_flag = #{signedFlag}
and v.confirm_status = #{confirmStatus}
and v.sign_type = #{signType}
order by v.project_id desc

SELECT v.* FROM ( SELECT ( SELECT hbt.description FROM hls_bp_type hbt WHERE hbt.bp_type = hbm.BP_TYPE ) bp_type_n, pp.project_id, pp.project_name, pp.project_number, pp.project_status, pp.document_type, pp.creation_date, (SELECT max( END_TIME_ ) FROM ACT_HI_PROCINST ahp WHERE ahp.BUSINESS_KEY_ = pp.PROJECT_ID AND INSTR( ahp.PROC_DEF_ID_, 'PRJ_PROJECT' ) > 0 and pp.project_status='APPROVED' ) approved_time, hbm.bp_name, hbm.bp_class, (SELECT hbt.description AS value_name FROM hls_business_type hbt WHERE hbt.document_category = 'HLS_BP_MASTER' AND hbt.business_type=hbm.bp_class) bp_class_n, pq.FINANCE_AMOUNT, pp.sign_type, pp.employee_id, pp.created_by, pp.org_sign_state, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'ORG_SIGN_STATE' AND v.ENABLED_FLAG = 'Y' AND v.code_value = pp.org_sign_state ) org_sign_state_n, pp.GUARANTEE_SIGNED_FLAG, ( SELECT s.MEANING FROM sys_code_value_b_v s WHERE s.CODE = 'GUARANTEE_SIGNED_FLAG' AND s.code_value = pp.guarantee_signed_flag ) guarantee_signed_flag_n, pp.lease_organization, ( SELECT fou.UNIT_NAME FROM fnd_org_unit fou WHERE pp.unit_id = fou.unit_id AND fou.ENABLED_FLAG = 'Y' ) lease_organization_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SIGN_METHOD' AND v.code_value = pp.sign_type ) sign_type_n, hdt.description document_type_n, ( SELECT fe.NAME FROM fnd_employee fe WHERE fe.employee_id = pp.employee_id ) employee_id_n, ( SELECT fe.NAME FROM fnd_employee fe WHERE fe.employee_id = pp.EMPLOYEE_ID_OF_MANAGER ) employee_id_of_manager_n, ( SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'PRJ501_PRJ_STATUS' AND v.code_id = b.code_id AND v. VALUE = pp.project_status ) project_status_n, pp.lease_channel, ( SELECT hlc.description FROM hls_lease_channel hlc WHERE hlc.lease_channel = pp.lease_channel ) lease_channel_n, pp.bp_id_vender, ( SELECT hb.bp_name FROM hls_bp_master hb WHERE hb.bp_id = pp.bp_id_vender ) bp_id_vender_n, ( SELECT hbv.bp_name FROM hls_bp_master hbv WHERE hbv.bp_id = pp.factory_id ) factory_name, ( SELECT hbv.bp_code FROM hls_bp_master hbv WHERE hbv.bp_id = pp.manufacturer_id ) manufacturer_code, ( SELECT hbv.bp_name FROM hls_bp_master hbv WHERE hbv.bp_id = pp.manufacturer_id ) manufacturer_name, pp.rejected_date, pp.rejected_description, pp.return_stage, ( SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'RETURN_STAGE' AND v.code_id = b.code_id AND v. VALUE = pp.return_stage ) return_stage_n, pp.return_type, ( SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'SIGN_RETURN_TYPE' AND v.code_id = b.code_id AND v. VALUE = pp.return_type ) return_type_n, PP.PARTNERS_CONTRACT_NUMBER, pp.partners_payment_number, pp.MANUFACTURER_ID, pp.TENANT_ID, pp.division, ( SELECT t.description FROM hls_division t WHERE t.division = pp.division AND t.enabled_flag = 'Y' ) division_n, pp.partners_contract_status, ( SELECT sv.MEANING FROM sys_code_value_b sv, sys_code_b b WHERE b.CODE = 'SY_CONTRACT_STATUS' AND sv.code_id = b.code_id AND sv. VALUE = pp.partners_contract_status ) partners_contract_status_n, pp.sign_status, decode(pp.sign_status,'NEW','未签约','SIGN','已签约','未签约') sign_status_n, pp.order_status, (select s.meaning from sys_code_value_b_v s where s.code = 'PRJ501_ORDER_STATUS' and s.code_value = pp.order_status) order_status_n, pp.lease_item_type, (SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'PRODUCT.LEASE_ITEM_TYPE' AND v.code_id = b.code_id AND v. VALUE = pp.lease_item_type) lease_item_type_n, nvl((select v.meaning from sys_code_value_b_v v where v.code='PRJ.ALIPAY_STATUS' and v.code_value=pp.alipay_status),'未签约') AS alipay_status_n FROM prj_project pp LEFT JOIN hls_bp_master hbm ON pp.TENANT_ID = hbm.bp_id LEFT JOIN hls_document_type hdt ON pp.DOCUMENT_TYPE = hdt.document_type LEFT JOIN prj_quotation pq ON pp.PROJECT_ID = pq.source_document_id ) v
v.PROJECT_STATUS = 'APPROVED'
and (v.created_by = #{createdBy} or EXISTS (SELECT 1 FROM sys_user U LEFT JOIN SYS_USER_ALLOCATION UR ON UR.USER_ID = U.USER_ID LEFT JOIN SYS_ROLE_B R ON R.ROLE_ID = UR.ROLE_ID WHERE R.ROLE_CODE in ('ADMIN','B0030','B0050') and U.USER_ID = #{createdBy}) OR exists( select 1 from fnd_org_unit a1,fnd_employee a2,fnd_employee_assigns a3,FND_ORG_POSITION a4 where a3.employee_id=a2.employee_id and a3.unit_id=a1.unit_id and a4.position_id=a3.position_id and a4.chief_position_flag='Y' and employee_code=#{request.employeeCode} AND A1.UNIT_ID IN(select b.unit_id from sys_user_allocation a,fnd_employee_assigns b where a.user_id=v.created_by AND a.employee_assign_id=b.employee_assign_id)) )
and v.division = #{division}
and v.bp_id = #{bpId}
and v.bp_name like concat('%',concat(#{bpName},'%'))
and v.bp_id_vender_n like concat('%',concat(#{vendor},'%'))
and trunc(v.creation_date) >= to_date(#{creationDateFrom},'yyyy-mm-dd')
and trunc(v.creation_date) <= to_date(#{creationDateTo},'yyyy-mm-dd')
and trunc(v.approved_time) >= to_date(#{approvedTimeFrom},'yyyy-mm-dd')
and trunc(v.approved_time) <= to_date(#{approvedTimeTo},'yyyy-mm-dd')
and v.factory_name like concat('%',concat(#{factoryName},'%'))
and v.manufacturer_name like concat('%',concat(#{manufacturerName},'%'))
and v.project_id = #{projectId}
and v.project_name like concat('%',concat(#{projectName},'%'))
and v.project_number like concat('%',concat(#{projectNumber},'%'))
and v.employee_id = #{employeeId}
and v.employee_id_n = #{employeeIdN}
and v.employee_id_of_manager = #{employeeIdOfManager}
and v.lease_channel = #{leaseChannel}
and v.document_type = #{documentType}
and v.project_status = #{projectStatus}
and v.partners_contract_number like concat('%',concat(#{partnersContractNumber},'%'))
and v.partners_payment_number like concat('%',concat(#{partnersPaymentNumber},'%'))
and v.signed_flag = #{signedFlag}
and v.confirm_status = #{confirmStatus}
and v.sign_type = #{signType}
order by v.project_id desc

SELECT v.*, (SELECT scvb.meaning FROM sys_code_value_b_v scvb WHERE scvb.CODE = 'PRJ_BUSINESS_STATUS' and scvb.code_value = v.business_status) business_status_n FROM ( SELECT CASE WHEN s2.slip_status = 'PAID' or s2.slip_status = 'DETAIL_SEND' THEN 'DONE' WHEN s2.slip_status = 'NEW' or s2.slip_status = 'BACK' then 'NEW' WHEN s2.slip_status = 'PAYING' or s2.slip_status = 'FAILURE' or s2.slip_status = 'INTERNAL_ERROR' or s2.slip_status = 'DETAIL_ERROR' or s2.slip_status = 'CANCLE' then 'PAYING' WHEN s2.slip_status = 'APPROVING' then 'REAPPROVING' WHEN s3.PAYMENT_REQ_STATUS = 'APPROVING' then 'APPROVING' WHEN s3.PAYMENT_REQ_STATUS = 'APPROVED' then 'APPROVED' ELSE 'NEW' END business_status, ( SELECT hbt.description FROM hls_bp_type hbt WHERE hbt.bp_type = hbm.BP_TYPE ) bp_type_n, pp.project_id, pp.project_name, pp.project_number, pp.project_status, pp.document_type, pp.creation_date, hbm.bp_name, hbm.bp_class, (SELECT hbt.description AS value_name FROM hls_business_type hbt WHERE hbt.document_category = 'HLS_BP_MASTER' AND hbt.business_type=hbm.bp_class) bp_class_n, pq.FINANCE_AMOUNT, pp.sign_type, pp.employee_id, pp.org_sign_state, nvl( pp.SIGN_STATUS, 'NEW' ) sign_status, ( SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'SIGN_STATUS' AND v.code_id = b.code_id AND v.value = nvl( pp.SIGN_STATUS, 'NEW' )) sign_status_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'ORG_SIGN_STATE' AND v.ENABLED_FLAG = 'Y' AND v.code_value = pp.org_sign_state ) org_sign_state_n, pp.signed_flag, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'SYS.YES_NO' and sc.code_value = pp.signed_flag) signed_flag_n, pp.GUARANTEE_SIGNED_FLAG, ( SELECT s.MEANING FROM sys_code_value_b_v s WHERE s.CODE = 'GUARANTEE_SIGNED_FLAG' AND s.code_value = pp.guarantee_signed_flag ) guarantee_signed_flag_n, pp.lease_organization, ( SELECT fou.UNIT_NAME FROM fnd_org_unit fou WHERE pp.LEASE_ORGANIZATION = fou.UNIT_CODE AND fou.ENABLED_FLAG = 'Y' ) lease_organization_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SIGN_METHOD' AND v.code_value = pp.sign_type ) sign_type_n, hdt.description document_type_n, ( SELECT fe.NAME FROM fnd_employee fe WHERE fe.employee_id = pp.employee_id ) employee_id_n, ( SELECT fe.NAME FROM fnd_employee fe WHERE fe.employee_id = pp.EMPLOYEE_ID_OF_MANAGER ) employee_id_of_manager_n, ( SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'PRJ501_PRJ_STATUS' AND v.code_id = b.code_id AND v.VALUE = pp.project_status ) project_status_n, pp.lease_channel, ( SELECT hlc.description FROM hls_lease_channel hlc WHERE hlc.lease_channel = pp.lease_channel ) lease_channel_n, pp.bp_id_vender, ( SELECT hb.bp_name FROM hls_bp_master hb WHERE hb.bp_id = pp.bp_id_vender ) bp_id_vender_n, ( SELECT hbv.bp_name FROM hls_bp_master hbv WHERE hbv.bp_id = pp.factory_id ) factory_name, ( SELECT hbv.bp_code FROM hls_bp_master hbv WHERE hbv.bp_id = pp.manufacturer_id ) manufacturer_code, ( SELECT hbv.bp_name FROM hls_bp_master hbv WHERE hbv.bp_id = pp.manufacturer_id ) manufacturer_name, pp.rejected_date, pp.rejected_description, pp.return_stage, ( SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'RETURN_STAGE' AND v.code_id = b.code_id AND v.VALUE = pp.return_stage ) return_stage_n, pp.return_type, ( SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'SIGN_RETURN_TYPE' AND v.code_id = b.code_id AND v.VALUE = pp.return_type ) return_type_n, PP.PARTNERS_CONTRACT_NUMBER, pp.partners_payment_number, pp.MANUFACTURER_ID, pp.factory_id, pp.TENANT_ID, pp.division, ( SELECT t.description FROM hls_division t WHERE t.division = pp.division AND t.enabled_flag = 'Y' ) division_n, pp.partners_contract_status, ( SELECT sv.MEANING FROM sys_code_value_b sv, sys_code_b b WHERE b.CODE = 'SY_CONTRACT_STATUS' AND sv.code_id = b.code_id AND sv.VALUE = pp.partners_contract_status ) partners_contract_status_n, pp.created_by, hbm.created_by as teanant_creted_by FROM prj_project pp LEFT JOIN hls_bp_master hbm ON pp.TENANT_ID = hbm.bp_id LEFT JOIN hls_document_type hdt ON pp.DOCUMENT_TYPE = hdt.document_type LEFT JOIN prj_quotation pq ON pp.PROJECT_ID = pq.source_document_id LEFT JOIN con_contract cc ON pp.project_id = cc.project_id LEFT JOIN con_contract_cashflow ccc ON cc.contract_id = ccc.contract_id AND ccc.cf_item = 0 LEFT JOIN (SELECT ccc.cashflow_id, sl.creation_date, sl.slip_status, row_number() over(PARTITION BY ccc.cashflow_id ORDER BY sl.creation_date) as row_flag from CSH_PAYMENT_REQ_SLIP sl, csh_payment_req_slip_ln sln, CSH_PAYMENT_REQ_LN LN, con_contract_cashflow ccc WHERE sl.slip_id = sln.slip_id AND sln.document_id = ln.payment_req_ln_id AND ln.source_doc_line_id = ccc.cashflow_id AND ccc.cf_item = 0 AND sl.slip_status != 'REJECTED') s2 ON CCC.CASHFLOW_ID = s2.cashflow_id and s2.row_flag = 1 LEFT JOIN (SELECT ccc.cashflow_id, hd.creation_date, hd.PAYMENT_REQ_STATUS, row_number() over(PARTITION BY ccc.cashflow_id ORDER BY hd.creation_date) as row_flag from CSH_PAYMENT_REQ_hd hd, CSH_PAYMENT_REQ_LN ln, con_contract_cashflow ccc WHERE hd.payment_req_id = ln.payment_req_id AND ln.SOURCE_DOC_LINE_ID = ccc.CASHFLOW_ID AND ccc.cf_item = 0 AND hd.PAYMENT_REQ_STATUS != 'BACK') s3 ON CCC.CASHFLOW_ID = s3.cashflow_id and s3.row_flag = 1 ) v
v.PROJECT_STATUS IN ('NEW','REJECTED','APPROVED_RETURN','CONDITIONAL','APPROVING','APPROVED','CANCEL','RETURN','BUSINESSAPPROVED') and v.DOCUMENT_TYPE IN ('PRJL','PRJLB')
and (exists( select 1 from fnd_org_unit fu, sys_user_allocation su,fnd_employee_assigns fa where su.user_id=#{createdBy} and su.EMPLOYEE_ASSIGN_ID=fa.EMPLOYEE_ASSIGN_ID and fa.unit_id =fu.unit_id and fu.unit_code != 'BUSINESS_DEPT_MANUFACTURER') OR exists( select 1 from fnd_employee a2,fnd_employee_assigns a3,FND_ORG_POSITION a4 where a3.employee_id=a2.employee_id and a4.position_id=a3.position_id and employee_code=#{request.employeeCode} AND A4.position_id IN(select b.position_id from sys_user_allocation a,fnd_employee_assigns b where a.employee_assign_id=b.employee_assign_id AND (a.user_id =v.created_by or a.user_id=v.teanant_creted_by) )) )
and v.division = #{division}
and v.bp_id = #{bpId}
and v.bp_name like concat('%',concat(#{bpName},'%'))
and v.bp_id_vender_n like concat('%',concat(#{vendor},'%'))
and trunc(v.creation_date) >= to_date(#{creationDateFrom},'yyyy-mm-dd')
and trunc(v.creation_date) <= to_date(#{creationDateTo},'yyyy-mm-dd')
and v.factory_name like concat('%',concat(#{factoryName},'%'))
and v.manufacturer_name like concat('%',concat(#{manufacturerName},'%'))
and v.project_id = #{projectId}
and v.project_name like concat('%',concat(#{projectName},'%'))
and v.project_number like concat('%',concat(#{projectNumber},'%'))
and v.employee_id = #{employeeId}
and v.employee_id_of_manager = #{employeeIdOfManager}
and v.lease_channel = #{leaseChannel}
and v.document_type = #{documentType}
and v.project_status = #{projectStatus}
and v.partners_contract_number like concat('%',concat(#{partnersContractNumber},'%'))
and v.partners_payment_number like concat('%',concat(#{partnersPaymentNumber},'%'))
and v.signed_flag = #{signedFlag}
and v.confirm_status = #{confirmStatus}
and v.sign_type = #{signType}
order by v.project_id desc

SELECT * FROM (select pp.PROJECT_ID, pp.PROJECT_NUMBER, pp.PROJECT_NAME, pp.FINANCE_AMOUNT, pp.LEASE_ITEM_AMOUNT, pp.PROJECT_DATE, pp.rejected_date, pp.rejected_description, pp.CREATION_DATE, pp.CREATED_BY, pp.OBJECT_VERSION_NUMBER, pp.LAST_UPDATE_DATE, pp.LAST_UPDATED_BY, pp.host_project_manager, PP.PARTNERS_CONTRACT_NUMBER, pp.partners_payment_number, pp.TENANT_ID, pp.DOCUMENT_TYPE, hdt.description document_type_n, pp.EMPLOYEE_ID, pp.investment_instance_id, (Select fe.Name From fnd_employee fe Where fe.EMPLOYEE_ID = pp.EMPLOYEE_ID) employee_id_n, pp.EMPLOYEE_ID_OF_MANAGER, (Select fe.NAME From fnd_employee fe Where fe.employee_id = pp.EMPLOYEE_ID_OF_MANAGER) employee_id_of_manager_n, pp.SIGN_DATE, pp.SIGN_TYPE, (select s.MEANING from sys_code_value_b_v s where s.code = 'SIGN_METHOD' and s.code_value = pp.sign_type) sign_type_n, pp.org_sign_state, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'ORG_SIGN_STATE' AND v.code_value = pp.org_sign_state ) org_sign_state_n, pp.signed_flag, (select sc.meaning value_name from sys_code_value_b_v sc where sc.code = 'SYS.YES_NO' and sc.code_value = pp.signed_flag) signed_flag_n, pp.GUARANTEE_SIGNED_FLAG, (select s.MEANING from sys_code_value_b_v s where s.code = 'GUARANTEE_SIGNED_FLAG' and s.code_value = pp.guarantee_signed_flag) guarantee_signed_flag_n, pp.CONFIRM_STATUS, (select s.MEANING from sys_code_value_b_v s where s.code = 'PRJ_CONFIRM_STATUS' and s.code_value = pp.confirm_status) confirm_status_n, pp.PROJECT_STATUS, (Select v.meaning From sys_code_value_b v, sys_code_b b Where b.CODE = 'PRJ501_PRJ_STATUS' and v.code_id = b.code_id And v.value = pp.project_status) project_status_n, nvl(pp.CONTRACT_TEXT_STATUS, 'UNCREATED') contract_text_status, (select s.MEANING from sys_code_value_b_v s where s.code = 'CONTRACT_TEXT_STATUS' and s.code_value = nvl(pp.CONTRACT_TEXT_STATUS, 'UNCREATED')) contract_text_status_n, pp.lease_channel, (Select hlc.description From hls_lease_channel hlc Where hlc.lease_channel = pp.lease_channel) lease_channel_n, pp.bp_id_vender, (Select hb.bp_name From hls_bp_master hb Where hb.bp_id = pp.bp_id_vender) bp_id_vender_n, pp.factory_id, (Select hbv.bp_name From hls_bp_master hbv Where hbv.bp_id = pp.factory_id) factory_name, pp.manufacturer_id, (Select hbv.bp_code From hls_bp_master hbv Where hbv.bp_id = pp.manufacturer_id) manufacturer_code, (Select hbv.bp_name From hls_bp_master hbv Where hbv.bp_id = pp.manufacturer_id) manufacturer_name,
pp.return_stage, (Select v.meaning From sys_code_value_b v, sys_code_b b Where b.CODE = 'RETURN_STAGE' and v.code_id = b.code_id And v.value = pp.return_stage) return_stage_n, pp.return_type, (Select v.meaning From sys_code_value_b v, sys_code_b b Where b.CODE = 'SIGN_RETURN_TYPE' and v.code_id = b.code_id And v.value = pp.return_type) return_type_n,
pp.lease_organization, (select fou.UNIT_NAME from fnd_org_unit fou where pp.unit_id = fou.unit_id and fou.ENABLED_FLAG='Y') lease_organization_n,
pp.division, (Select t.description From hls_division t Where t.division = pp.division And t.enabled_flag = 'Y') division_n, pp.partners_contract_status, (select sv.MEANING from sys_code_value_b sv, sys_code_b b where b.CODE = 'SY_CONTRACT_STATUS' and sv.code_id = b.code_id and sv.value = pp.partners_contract_status) partners_contract_status_n, pp.DE_APPLY_RESULT, (SELECT b.meaning AS value_name FROM sys_code_b a, sys_code_value_b b WHERE a.code_id = b.code_id AND a.code = 'DE_APPLY_RESULT' AND b.enabled_flag = 'Y' AND b.value = pp.de_apply_result) de_apply_result_n, hbm.bp_name, (Select pqt.int_rate From prj_quotation pqt Where pqt.SOURCE_DOCUMENT_ID = pp.PROJECT_ID And pqt.source_document_category = 'PRJ_PROJECT' and pqt.enabled_flag ='Y') int_rate, (Select Sum(pqc.due_amount) From prj_quotation_cashflow pqc, prj_quotation pqt Where pqc.cf_item = 51 And pqc.cf_type = 5 And pqc.quotation_id = pqt.quotation_id And pqt.SOURCE_DOCUMENT_ID = pp.PROJECT_ID And pqt.source_document_category = 'PRJ_PROJECT') sum_deposit, (Select Sum(pqc1.due_amount) From prj_quotation_cashflow pqc1, prj_quotation pqt Where pqc1.cf_item = 65 And pqc1.cf_type = 65 And pqc1.quotation_id = pqt.quotation_id And pqt.SOURCE_DOCUMENT_ID = pp.PROJECT_ID And pqt.source_document_category = 'PRJ_PROJECT') sum_commission, ( SELECT sum(pc.due_amount) FROM prj_quotation pq, prj_quotation_cashflow pc WHERE pc.QUOTATION_ID = pq.QUOTATION_ID AND pc.CF_ITEM = 66 And pc.cf_type = 65 AND pq.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT' AND pq.SOURCE_DOCUMENT_ID = pp.PROJECT_ID ) AS SUM_COMMISSION_DISCOUNT, pp.sign_status, decode(pp.sign_status,'NEW','未签约','SIGN','已签约','未签约')sign_status_n, pp.business_type, (SELECT hdt.description FROM hls_document_type hdt WHERE hdt.business_type = pp.business_type AND hdt.document_category = pp.document_category AND hdt.document_type = pp.document_type ) AS business_type_n, pp.order_status, (select s.meaning from sys_code_value_b_v s where s.code = 'PRJ501_ORDER_STATUS' and s.code_value = pp.order_status) order_status_n, decode((select count(1) from con_contract cc, con_contract_cashflow ccc where cc.contract_id = ccc.contract_id and ccc.cf_item = 0 and ccc.cf_type = 0 and ccc.cf_direction = 'OUTFLOW' and ccc.cf_status = 'RELEASE' and ccc.write_off_flag ='FULL' and cc.project_id = pp.project_id),0,'未支付',1,'支付成功') payment_result_n, pp.investment_status, (Select v.meaning From sys_code_value_b v, sys_code_b b Where b.CODE = 'INVESTMENT_STATUS' and v.code_id = b.code_id And v.value = nvl(pp.investment_status, 'NEW')) investment_status_n, (SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'PRODUCT.LEASE_ITEM_TYPE' AND v.code_id = b.code_id AND v. VALUE = pp.lease_item_type) lease_item_type_n From prj_project pp Left Join hls_bp_master hbm On pp.TENANT_ID = hbm.bp_id Left Join hls_document_type hdt On pp.DOCUMENT_TYPE = hdt.document_type
pp.PROJECT_STATUS = 'APPROVED' and pp.DOCUMENT_TYPE not in ('CREDIT', 'FACTORING') and (select fou.UNIT_CODE from fnd_org_unit fou where pp.unit_id = fou.unit_id and fou.ENABLED_FLAG='Y') = 'VEHICLE_RENTAL_DEPARTMENT'
and (exists( select 1 from fnd_org_unit fu, sys_user_allocation su,fnd_employee_assigns fa where su.user_id=#{createdBy} and su.EMPLOYEE_ASSIGN_ID=fa.EMPLOYEE_ASSIGN_ID and fa.unit_id =fu.unit_id and fu.unit_code != 'BUSINESS_DEPT_MANUFACTURER') OR exists( select 1 from sys_user_allocation a2,fnd_employee_assigns a3,FND_ORG_POSITION a4 where a3.EMPLOYEE_ASSIGN_ID=a2.EMPLOYEE_ASSIGN_ID and a4.position_id=a3.position_id and a2.user_id=#{createdBy} AND A4.position_id IN (select b.position_id from sys_user_allocation a,fnd_employee_assigns b where a.employee_assign_id=b.employee_assign_id AND a.user_id =PP.created_by)) )
and pp.division = #{division}
and decode((Select Count(*) From prj_project_attachment pa, hls_doc_file_templet ht, fnd_atm_attachment_multi fm, fnd_atm_attachment fa, yx_anxinsign_batch_detail bd Where pp.project_id = pa.project_id And pa.project_attachment_category = 'ONLINE_SIGN_CONTRACT' And pa.last_sign_flag = 'Y' And pa.source_id = ht.templet_id And ht.org_sign_flag = 'Y' And fm.table_name = pa.project_attachment_category And fm.table_pk_value = to_char(pa.project_attachment_id) And fa.attachment_id = fm.attachment_id And bd.attchment_id = pa.project_attachment_id And bd.batch_id = (Select Max(b.batch_id) From yx_anxinsign_batch_detail b Where b.attchment_id = pa.project_attachment_id And b.create_timestamp = (Select Max(b1.create_timestamp) From yx_anxinsign_batch_detail b1 Where b1.attchment_id = pa.project_attachment_id)) And bd.signment_state = 1), 0, 'N', (Select Count(*) From prj_project_attachment pa, hls_doc_file_templet ht, fnd_atm_attachment_multi fm, fnd_atm_attachment fa Where pp.project_id = pa.project_id And pa.project_attachment_category = 'ONLINE_SIGN_CONTRACT' And pa.last_sign_flag = 'Y' And pa.source_id = ht.templet_id And ht.org_sign_flag = 'Y' And fm.table_name = pa.project_attachment_category And fm.table_pk_value = to_char(pa.project_attachment_id) And fa.attachment_id = fm.attachment_id), 'Y', 'N') = #{orgSignState}
and (select hbm.bp_name from hls_bp_master hbm where pp.TENANT_ID = hbm.bp_id) like concat('%',concat(#{bpName},'%'))
and (select fct.bp_name from hls_bp_master fct where fct.bp_id = pp.factory_id) like concat('%',concat(#{factoryNameN},'%'))
and exists(select 1 from hls_bp_master m where m.bp_name like #{vendorN} and m.bp_id = pp.bp_id_vender)
and pp.sign_status = #{signStatus}
and pp.guarantee_signed_flag = #{guaranteeSignedFlag}
and pp.creation_date >= to_date(#{creationDateFrom},'yyyy-mm-dd')
and pp.creation_date <= to_date(#{creationDateTo},'yyyy-mm-dd')
and trunc(pp.sign_date) >= to_date(#{signDateFrom},'yyyy-mm-dd')
and trunc(pp.sign_date) <= to_date(#{signDateTo},'yyyy-mm-dd')
and trunc(pp.project_date) >= to_date(#{projectDateFrom},'yyyy-mm-dd')
and trunc(pp.project_date) <= to_date(#{projectDateTo},'yyyy-mm-dd')
and pp.project_id = #{projectId}
and pp.project_name like concat('%',concat(#{projectName},'%'))
and pp.project_number like concat('%',concat(#{projectNumber},'%'))
and pp.employee_id = #{employeeId}
and pp.host_project_manager = #{hostProjectManager}
and pp.lease_channel = #{leaseChannel}
and pp.document_type = #{documentType}
and pp.project_status = #{projectStatus}
and pp.finance_amount >= #{financeAmountFrom}
and pp.finance_amount <= #{financeAmountTo}
and nvl((select pqt.int_rate from prj_quotation pqt where pqt.SOURCE_DOCUMENT_ID = pp.PROJECT_ID and pqt.source_document_category = 'PRJ_PROJECT' and pqt.data_class is null),0)>= #{intRateFrom}
and nvl((select pqt.int_rate from prj_quotation pqt where pqt.SOURCE_DOCUMENT_ID = pp.PROJECT_ID and pqt.source_document_category = 'PRJ_PROJECT' and pqt.data_class is null),0) <= #{intRateTo}
and pp.contract_text_status = #{contractTextStatus}
and pp.signed_flag = #{signedFlag}
and pp.confirm_status = #{confirmStatus}
and pp.sign_type = #{signType}
and nvl(pp.investment_status, 'NEW') = #{investmentStatus}
and pp.lease_item_type = #{leaseItemType}
and decode((select count(1) from con_contract cc, con_contract_cashflow ccc where cc.contract_id = ccc.contract_id and ccc.cf_item = 0 and ccc.cf_type = 0 and ccc.cf_direction = 'OUTFLOW' and ccc.cf_status = 'RELEASE' and ccc.write_off_flag ='FULL' and cc.project_id = pp.project_id),0,'未支付',1,'支付成功') = #{paymentResultN}
) temp where 1=1
and sum_deposit >= #{sumDepositFrom}
and sum_deposit <= #{sumDepositTo}
and sum_commission >= #{sumCommissionFrom}
and sum_commission <= #{sumCommissionTo}
and de_apply_result = #{deApplyResult}
and manufacturer_name like concat('%',concat(#{manufacturerName},'%'))
order by project_id desc

select v.*,v.lease_item_amount-v.used_amount left_amount from (select c.change_req_id, '第' || c.document_version_id || '次变更' document_version_id, c.status, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb. CODE = 'CHANGE_REQ_STATUS' AND scb.code_id = scvb.code_id AND scvb.enabled_flag = 'Y' and scvb.value = c.status) status_n, c.change_req_date, c.change_description, (select su.description from sys_user su where su.user_id = c.change_req_user_id) change_req_user_name, c.document_id source_project_id, c.change_info_desc, c.change_effct_desc, c.instance_end_flag, c.change_req_number, pp.project_id, pp.project_number, pp.project_name, pp.tenant_id, (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = pp.tenant_id) bp_name, (SELECT q.CREDIT_AMT FROM hls_credit_plan q WHERE q.SOURCE_DOCUMENT_ID = pp.project_id AND q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT') lease_item_amount, /*这里要等付款支付改造完成后取值*/ 0 used_amount, (SELECT q.cyclical_amount FROM hls_credit_plan q WHERE q.SOURCE_DOCUMENT_ID = pp.project_id AND q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT') cyclical_amount, (SELECT q.non_cyclical_amount FROM hls_credit_plan q WHERE q.SOURCE_DOCUMENT_ID = pp.project_id AND q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT') non_cyclical_amount, pp.host_project_manager, (select su.description from sys_user su where su.user_id = pp.host_project_manager) host_project_manager_n, pp.unit_id, (SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = pp.unit_id) unit_id_n, pp.assist_project_manager, (SELECT a.description FROM sys_user a WHERE a.user_id= pp.assist_project_manager) assist_project_manager_n, pp.assist_unit_id, (SELECT fou.unit_name FROM fnd_org_unit fou WHERE fou.unit_id = pp.assist_unit_id ) assist_unit_id_n, (SELECT fe. NAME FROM fnd_org_unit fou, fnd_org_position fop, fnd_employee_assigns fea, fnd_employee fe WHERE fou.unit_id = pp.unit_id AND fou.unit_id = fop.unit_id AND fop.chief_position_flag = 'Y' AND fop.position_id = fea.position_id AND fea.employee_id = fe.employee_id and fe.ENABLED_FLAG = 'Y' and fea.ENABLED_FLAG = 'Y') project_manager_n, pp.project_status, (SELECT t1.description FROM hls_document_status t1 WHERE t1.document_category = 'PRJ_PROJECT' and t1.enabled_flag = 'Y' AND t1.status_code = pp.project_status) project_status_n, pp.company_id, (select t.company_full_name from fnd_company t where t.company_id=pp.company_id) company_id_n, pp.is_low_risk, (select scvb.meaning from sys_code_b scb, sys_code_value_b scvb where scb. CODE = 'PROJECT_GROUP' AND scb.code_id = scvb.code_id AND scvb.enabled_flag = 'Y' and scvb.value = pp.is_low_risk) as is_low_risk_n, pp.org_sign_state, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'ORG_SIGN_STATE' and v.ENABLED_FLAG = 'Y' AND v.code_value = pp.org_sign_state ) org_sign_state_n, (SELECT q.date_from FROM hls_credit_plan q WHERE q.SOURCE_DOCUMENT_ID = pp.project_id AND q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT') valid_from, (SELECT q.date_to FROM hls_credit_plan q WHERE q.SOURCE_DOCUMENT_ID = pp.project_id AND q.SOURCE_DOCUMENT_CATEGORY = 'PRJ_PROJECT') valid_to from change_req_info c,prj_project pp where c.document_category = 'PRJ_PROJECT' and pp.data_type in ('CHANGE_REQ') and c.change_req_id = pp.change_req_id and c.change_type='PRJ_AMOUNT_ALLOCATE' order by c.document_version_id desc ) v
1=1
and v.project_id = #{projectId}

select fba.base_rate from
        fnd_base_rate fba,fnd_base_rate_set fbes
where
        fba.base_rate_set = fbes.base_rate_set
  and fbes.valid_from <= trunc(sysdate)
  and (fbes.valid_to >= trunc(sysdate) or fbes.valid_to is null)
  and fba.months_from <= #{leaseTerm}
  and fba.months_to >= #{leaseTerm}
  and fbes.base_rate_type = #{baseRateType}

select pp.project_id,pp.project_number,pp.project_name,pp.short_name,pp.document_type, pp.project_class,pp.tenant_id,pp.bp_class,pp.industry_type,pp.project_status,pp.property_type, pp.chance_id,pp.employee_id,pp.employee_id_of_manager,pp.lease_organization,pp.future_lease_term, pp.future_xirr,pp.lease_channel,pp.business_type,pp.division,pp.financing_purpose,pp.lease_start_date,pp.description, hbm.bp_name tenant_name,hbm.bp_code,
(select hd.description from hls_division hd where hd.division = pp.DIVISION)division_n, (SELECT bt.description FROM hls_business_type bt where bt.document_category = 'HLS_BP_MASTER' and bt.business_type = pp.BP_CLASS )bp_class_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'PROJECT_TYPE' AND v.code_value = pp.project_class ) project_class_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'INDUSTRY_TYPE' AND v.code_value = pp.industry_type ) industry_type_n, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'PROPERTY_TYPE' AND v.code_value = pp.property_type ) property_type_n, ( SELECT v.description value_name FROM hls_document_type v WHERE V.enabled_flag = 'Y' AND v.document_category ='PRJ_PROJECT' AND v.document_type = pp.document_type ) document_type_n, (select bt.description from hls_business_type bt where bt.document_category ='PRJ_PROJECT' and bt.business_type = pp.business_type)business_type_n, (SELECT hbm.bp_name FROM hls_bp_master hbm where hbm.bp_id = pp.tenant_id )tenant_id_n, ( SELECT t1.description FROM hls_lease_channel t1 WHERE t1.lease_channel = pp.lease_channel )lease_channel_n, ( select fe.NAME from fnd_employee fe where fe.employee_id = pp.employee_id )employee_id_n, ( select fe.NAME from fnd_employee fe where fe.employee_id = pp.EMPLOYEE_ID_OF_MANAGER )employee_id_of_manager_n, ( select fou.UNIT_NAME from fnd_org_unit fou where pp.LEASE_ORGANIZATION=fou.UNIT_CODE and fou.ENABLED_FLAG='Y' ) lease_organization_n,
( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'PRJ501_PRJ_STATUS' AND v.code_value = pp.project_status ) project_status_n, pp.factory_id, (select hb.bp_name from hls_bp_master hb where hb.bp_id = pp.factory_id) factory_id_n, pp.bp_id_vender, (select hb.bp_name from hls_bp_master hb where hb.bp_id = pp.bp_id_vender) bp_id_vender_n, pp.insurance_flag, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'INSURANCE_PURCHASE_STATUS' AND v.code_value = pp.insurance_flag ) insurance_flag_n, pp.floating_range_method, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'CON.FLOATING_RANGE_METHOD' AND v.code_value = pp.floating_range_method ) floating_range_method_n, pp.base_rate_type, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'FND.BASE_RATE_TYPE' AND v.code_value = pp.base_rate_type ) base_rate_type_n, pp.second_hand_flag, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'PRJ_EQUIPMENT_TYPE' AND v.code_value = pp.second_hand_flag ) second_hand_flag_n, pp.vender_mode_flag, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'SYS.YES_NO' AND v.code_value = pp.vender_mode_flag ) vender_mode_flag_n, pp.sign_type, ( SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SIGN_METHOD' AND v.code_value = pp.sign_type ) sign_type_n from prj_project pp LEFT JOIN hls_bp_master hbm on hbm.bp_id = pp.tenant_id where pp.project_id = #{projectId}

select v.*, (SELECT scvb.meaning FROM sys_code_value_b_v scvb WHERE scvb.CODE = 'PRJ_BUSINESS_STATUS' and scvb.code_value = v.business_status) business_status_n from (SELECT CASE WHEN s2.slip_status = 'PAID' or s2.slip_status = 'DETAIL_SEND' THEN 'DONE' WHEN s2.slip_status = 'NEW' or s2.slip_status = 'BACK' then 'NEW' WHEN s2.slip_status = 'PAYING' or s2.slip_status = 'FAILURE' or s2.slip_status = 'INTERNAL_ERROR' or s2.slip_status = 'DETAIL_ERROR' or s2.slip_status = 'CANCLE' then 'PAYING' WHEN s2.slip_status = 'APPROVING' then 'REAPPROVING' WHEN s3.PAYMENT_REQ_STATUS = 'APPROVING' then 'APPROVING' WHEN s3.PAYMENT_REQ_STATUS = 'APPROVED' then 'APPROVED' ELSE 'NEW' END business_status, pp.project_id, pp.project_number, pp.project_status, pp.lease_channel, pp.document_type, CASE WHEN cc.contract_id is not null THEN 'APPROVED' ELSE pp.sign_status END sign_status, hbm.bp_name, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v. CODE = 'PRJ501_PRJ_STATUS' AND v.code_value = pp.project_status) project_status_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'SIGN_STATUS' AND v.code_value = sign_status) sign_status_n, pp.bp_id_vender, (select hbv.bp_name from hls_bp_master hbv where hbv.bp_id = pp.bp_id_vender) bp_id_vender_n, (select hbv.bp_name from hls_bp_master hbv where hbv.bp_id = pp.manufacturer_id) manufacturer_name, (select hbv.bp_name from hls_bp_master hbv where hbv.bp_id = pp.seller_id) seller_id_n, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'CON.CONTRACT_STATUS' AND v.code_value = cc.contract_status) contract_status_n, cc.contract_status FROM prj_project pp LEFT JOIN hls_bp_master hbm ON pp.tenant_id = hbm.bp_id LEFT JOIN con_contract cc ON pp.project_id = cc.project_id LEFT JOIN con_contract_cashflow ccc ON cc.contract_id = ccc.contract_id AND ccc.cf_item = 0 LEFT JOIN (SELECT ccc.cashflow_id, sl.creation_date, sl.slip_status, row_number() over(PARTITION BY ccc.cashflow_id ORDER BY sl.creation_date) as row_flag from CSH_PAYMENT_REQ_SLIP sl, csh_payment_req_slip_ln sln, CSH_PAYMENT_REQ_LN LN, con_contract_cashflow ccc WHERE sl.slip_id = sln.slip_id AND sln.document_id = ln.payment_req_ln_id AND ln.source_doc_line_id = ccc.cashflow_id AND ccc.cf_item = 0 AND sl.slip_status != 'REJECTED') s2 ON CCC.CASHFLOW_ID = s2.cashflow_id and s2.row_flag = 1 LEFT JOIN (SELECT ccc.cashflow_id, hd.creation_date, hd.PAYMENT_REQ_STATUS, row_number() over(PARTITION BY ccc.cashflow_id ORDER BY hd.creation_date) as row_flag from CSH_PAYMENT_REQ_hd hd, CSH_PAYMENT_REQ_LN ln, con_contract_cashflow ccc WHERE hd.payment_req_id = ln.payment_req_id AND ln.SOURCE_DOC_LINE_ID = ccc.CASHFLOW_ID AND ccc.cf_item = 0 AND hd.PAYMENT_REQ_STATUS != 'BACK') s3 ON CCC.CASHFLOW_ID = s3.cashflow_id and s3.row_flag = 1 where pp.document_type in('PRJLB','PRJL')) v
and v.manufacturer_name like concat('%',concat(#{manufacturer_name},'%'))
and v.project_number like concat('%',concat(#{project_number},'%'))
and v.bp_name like concat('%',concat(#{bp_name},'%'))
and v.bp_id_vender_n like concat('%',concat(#{vendor},'%'))
and v.sign_status = #{sign_status}
and v.business_status = #{business_status}
and v.project_status = #{project_status}
and v.contract_status = #{contract_status}
order by v.project_id desc

