SELECT v.* FROM (SELECT pp.project_id, pp.project_name, pp.project_number, pp.project_status, pp.document_type, pp.creation_date, hbm.bp_name, hbm.bp_class, pp.FINANCE_AMOUNT, pp.employee_id, (SELECT fe.NAME FROM fnd_employee fe WHERE fe.employee_id = pp.employee_id) employee_id_n, pp.created_by, pp.lease_organization, (SELECT fou.UNIT_NAME FROM fnd_org_unit fou WHERE pp.unit_id = fou.unit_id AND fou.ENABLED_FLAG = 'Y') lease_organization_n, (SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'PRJ501_PRJ_STATUS' AND v.code_id = b.code_id AND v. VALUE = pp.project_status) project_status_n, pp.business_type, (SELECT hdt.description FROM hls_document_type hdt WHERE hdt.business_type = pp.business_type AND hdt.document_category = pp.document_category AND hdt.document_type = pp.document_type) AS business_type_n, pp.lease_channel, (SELECT hlc.description FROM hls_lease_channel hlc WHERE hlc.lease_channel = pp.lease_channel) lease_channel_n, (SELECT hbv.bp_name FROM hls_bp_master hbv WHERE hbv.bp_id = pp.manufacturer_id) manufacturer_name, pp.MANUFACTURER_ID, pp.TENANT_ID, pp.division, (SELECT t.description FROM hls_division t WHERE t.division = pp.division AND t.enabled_flag = 'Y') division_n, pp.pre_status, (select s.meaning from sys_code_value_b_v s where s.code = 'PRJ501_PRE_STATUS' and s.code_value = pp.pre_status) pre_status_n, pp.order_status, (select s.meaning from sys_code_value_b_v s where s.code = 'PRJ501_ORDER_STATUS' and s.code_value = pp.order_status) order_status_n, (SELECT sv.MEANING FROM sys_code_value_b sv, sys_code_b b WHERE b.CODE = 'DRIVER_AND_APPLICANT' AND sv.code_id = b.code_id AND sv.VALUE= pp.driver_and_applicant) driver_and_applicant, pp.process_instance_id, pp.approved_date, pp.lease_item_type, (SELECT v.meaning FROM sys_code_value_b v, sys_code_b b WHERE b.CODE = 'PRODUCT.LEASE_ITEM_TYPE' AND v.code_id = b.code_id AND v. VALUE = pp.lease_item_type) lease_item_type_n, pp.document_category, pp.DATA_CLASS FROM prj_project pp LEFT JOIN hls_bp_master hbm ON pp.TENANT_ID = hbm.bp_id) v
and v.document_type != 'FACTORING'
and (v.created_by = #{createdBy} or exists( select 1 from fnd_org_unit fu, sys_user_allocation su,fnd_employee_assigns fa where su.user_id=#{createdBy} and su.EMPLOYEE_ASSIGN_ID=fa.EMPLOYEE_ASSIGN_ID and fa.unit_id =fu.unit_id and fu.unit_code != 'BUSINESS_DEPT_MANUFACTURER') )
and v.bp_name like concat('%',concat(#{bpName},'%'))
and v.manufacturer_name like concat('%',concat(#{manufacturerName},'%'))
and v.project_number like concat('%',concat(#{projectNumber},'%'))
and v.employee_id_n = #{employeeIdN}
and v.pre_status = #{preStatus}
and v.project_status = #{projectStatus}
and v.lease_item_type = #{leaseItemType}
and trunc(v.creation_date) >= to_date(#{creationDateFrom},'yyyy-mm-dd')
and trunc(v.creation_date) <= to_date(#{creationDateTo},'yyyy-mm-dd')
and v.finance_amount >= #{financeAmountFrom}
and v.finance_amount <= #{financeAmountTo}
order by v.project_id desc

SELECT cc.contract_id, cc.CONTRACT_NUMBER, ( SELECT hbv.bp_name FROM hls_bp_master hbv WHERE hbv.bp_id = pp.tenant_id ) tenant_id_n, ( SELECT m.id_card_no FROM hls_bp_master m WHERE m.bp_id = pp.tenant_id ) id_card_no, ( SELECT m.phone FROM hls_bp_master m WHERE m.bp_id = pp.tenant_id ) phone, ( SELECT bt.description FROM hls_business_type bt WHERE bt.DOCUMENT_CATEGORY = 'CON_CONTRACT' AND bt.business_type = cc.business_type ) business_type_n, ( SELECT hbv.bp_name FROM hls_bp_master hbv WHERE hbv.bp_id = cc.manufacturer_id ) manufacturer_id_n, (SELECT sv.MEANING FROM sys_code_value_b sv, sys_code_b b WHERE b.CODE = 'DRIVER_AND_APPLICANT' AND sv.code_id = b.code_id AND sv.VALUE= pp.driver_and_applicant) driver_and_applicant, ( SELECT i.frame_number FROM prj_project_lease_item i WHERE i.project_id = pp.project_id ) frame_number, ( SELECT i.model_c FROM prj_project_lease_item i WHERE i.project_id = pp.project_id ) model_c, ( SELECT i.brand_c FROM prj_project_lease_item i WHERE i.project_id = pp.project_id ) brand_c, ( SELECT i.color_c FROM prj_project_lease_item i WHERE i.project_id = pp.project_id ) color_c, ( SELECT i.list_price FROM prj_project_lease_item i WHERE i.project_id = pp.project_id ) list_price, ( SELECT finance_amount FROM prj_quotation q WHERE q.source_document_category = 'PRJ_PROJECT' AND q.source_document_id = pp.project_id ) finance_amount, ( SELECT lease_times FROM prj_quotation q WHERE q.source_document_category = 'PRJ_PROJECT' AND q.source_document_id = pp.project_id ) lease_times, ( SELECT down_payment FROM prj_quotation q WHERE q.source_document_category = 'PRJ_PROJECT' AND q.source_document_id = pp.project_id ) down_payment , ( SELECT pmt FROM prj_quotation q WHERE q.source_document_category = 'PRJ_PROJECT' AND q.source_document_id = pp.project_id) pmt FROM CON_CONTRACT cc left join prj_project pp on cc.project_id=pp.project_id where 1=1
and cc.contract_id = #{contractId}
and pp.project_id = #{projectId}

SELECT pp.contract_content_number as contract_content_number, -- 合同用印份数 pp.contract_sign_address as contract_sign_address, -- 合同签订地点 pp.contract_sign_times as contract_sign_times, -- 合同签订日期 pp.contract_special_condit as contract_special_condit, -- 合同特别约定条款 pp.contract_out_law_name as contract_out_law_name, -- 外聘律师事务所机构名称 pp.contract_out_law_reviewer as contract_out_law_reviewer, -- 外聘律师事务所审查人 pp.contract_out_law_date as contract_out_law_date, -- 外聘律师事务所审查日期 pp.contract_out_law_comment as contract_out_law_comment, -- 外聘律师事务所审查意见 pp.project_id, pp.project_number, pp.project_name, pp.contract_number, pp.industry, pp.tenant_id, pp.credit_measures, pp.credit_flag, (SELECT v.meaning FROM sys_code_value_b_v v WHERE v.CODE = 'GT.HCLC.CREDIT_FLAG' AND pp.CREDIT_FLAG = v.CODE_VALUE) AS credit_flag_n, ( SELECT hbv.bp_name FROM hls_bp_master hbv WHERE hbv.bp_id = pp.tenant_id ) tenant_id_n, pp.company_id, ( SELECT FC.COMPANY_FULL_NAME FROM FND_COMPANY FC WHERE pp.COMPANY_ID = FC.COMPANY_ID ) COMPANY_ID_N, pp.creation_date, pp.unit_id, ( SELECT fou.unit_name FROM fnd_org_unit fou WHERE pp.unit_id = fou.unit_id ) unit_id_n, pp.host_project_manager, ( SELECT su.description FROM sys_user su WHERE su.user_id = pp.host_project_manager ) host_project_manager_n, pp.assist_project_manager, ( SELECT a.description FROM sys_user a WHERE a.user_id = pp.assist_project_manager ) assist_project_manager_n, pp.city, ( SELECT CONCAT( ( SELECT P.DESCRIPTION FROM FND_PROVINCE P WHERE to_char( P.PROVINCE ) = fd.PROVINCE ), CONCAT( ( SELECT fc.DESCRIPTION FROM FND_CITY fc WHERE to_char( fc.City ) = fd.City ), fd.DESCRIPTION ) ) FROM fnd_district fd WHERE fd.DISTRICT = pp.city AND fd.enabled_flag = 'Y' ) CITY_N, pp.factoring_type, ( SELECT sc.meaning FROM sys_code_value_b_v sc WHERE sc.code = 'CHANCE.FACTORING_TYPE' AND sc.code_value = pp.factoring_type ) factoring_type_n, pp.factoring_category, ( SELECT sc.meaning FROM sys_code_value_b_v sc WHERE sc.code = 'CHANCE.FACTORING_CATEGORY' AND sc.code_value = pp.factoring_category ) factoring_category_n, pp.factoring_recourse, ( SELECT sc.meaning FROM sys_code_value_b_v sc WHERE sc.code = 'CHANCE.FACTORING_RECOURSE' AND sc.code_value = pp.factoring_recourse ) factoring_recourse_n, pp.factoring_open, ( SELECT sc.meaning FROM sys_code_value_b_v sc WHERE sc.code = 'CHANCE.FACTORING_OPEN' AND sc.code_value = pp.factoring_open ) factoring_open_n, pp.industry_type, ( SELECT hsc.description FROM hls_stat_class hsc WHERE to_char( hsc.class_id ) = pp.industry_type AND hsc.enabled_flag = 'Y' ) industry_type_n, pp.CONTRACT_STATUS, (select v.meaning FROM sys_code_value_b_v v WHERE v.code = 'HLS.WORK_FLOW_STATUS' AND v.code_value = pp.contract_status) contract_status_n, pp.CONTRACT_END_DATE, pp.document_type, pp.document_category, pp.data_class FROM PRJ_PROJECT pp
pp.document_type = 'FACTORING' AND pp.document_category = 'PRJ_PROJECT' AND pp.data_class = 'VIRTUAL_CON'
and pp.project_id = #{projectId}
